'use strict';
const paths={orbit:'M12 2v5m0 10v5M3.3 7l4.4 2.5m8.6 5 4.4 2.5M3.3 17l4.4-2.5m8.6-5L20.7 7M12 11a1 1 0 1 0 0 2 1 1 0 1 0 0-2',home:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16M8 14h2M14 14h2M8 18h2',chat:'M21 11.5a8.5 8.5 0 0 1-8.5 8.5H5l-3 2 1.5-6A8.5 8.5 0 1 1 21 11.5Z',bot:'M5 7h14v13H5zM12 3v4M2 11v5M22 11v5M9 12h.01M15 12h.01M9 16h6',gallery:'M3 3h18v18H3zM3 17l6-6 5 5 3-3 4 4M15 7h.01',wallet:'M20 7H4V4h14v3M4 7v13h17V7H4ZM16 12h5v4h-5z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 1 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',star:'m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1L2.2 9.4l6.1-.9z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 1 0 0-8M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',moon:'M21 13a9 9 0 0 1-10-10A9 9 0 1 0 21 13Z',down:'m7 10 5 5 5-5',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18M12 7v5l3 2',users:'M9 3a3 3 0 1 0 0 6 3 3 0 1 0 0-6M3 20v-4a6 6 0 0 1 12 0v4M17 4a3 3 0 0 1 0 6M18 14a4 4 0 0 1 3 4v2',info:'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18M12 11v6M12 7h.01',phone:'M7 2h10v20H7zM10 18h4',send:'m3 3 18 9-18 9 3-9-3-9ZM6 12h15',scissors:'M6 3a3 3 0 1 0 0 6 3 3 0 1 0 0-6M6 15a3 3 0 1 0 0 6 3 3 0 1 0 0-6M8 8l13 12M8 16 21 3',chevron:'m9 5 7 7-7 7',logout:'M10 4H4v16h6M13 12h8M17 8l4 4-4 4',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2V3ZM9 8h6M9 12h6',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const initial=()=>({theme:'dark',agents:[{id:'central',label:'Central da barbearia',name:'Luna',personality:'Acolhedora e objetiva',professional:'Todos',phone:'Número de demonstração',paused:false},{id:'joao',label:'João · Barbeiro',name:'Theo',personality:'Descontraído e direto',professional:'João',phone:'Número de demonstração',paused:false},{id:'lucas',label:'Lucas · Barbeiro',name:'Maya',personality:'Simpática e atenciosa',professional:'Lucas',phone:'Número de demonstração',paused:false}],bookings:[{id:'b1',client:'Gabriel Oliveira',professional:'João',service:'Corte + barba',time:'09:00',date:today(),duration:60,price:75,status:'Concluído',channel:'central'},{id:'b2',client:'Rafael Costa',professional:'Lucas',service:'Corte masculino',time:'10:00',date:today(),duration:30,price:45,status:'Concluído',channel:'lucas'},{id:'b3',client:'Matheus Silva',professional:'João',service:'Corte masculino',time:'14:00',date:today(),duration:30,price:45,status:'Confirmado',channel:'joao'},{id:'b4',client:'Bruno Santos',professional:'Lucas',service:'Corte + barba',time:'15:00',date:today(),duration:60,price:75,status:'Confirmado',channel:'central'}],entries:[{id:'e1',label:'Atendimentos anteriores · exemplo',amount:1160,type:'income'},{id:'e2',label:'Despesas do período · exemplo',amount:260,type:'expense'}],gallery:[]});
let state;try{state=JSON.parse(localStorage.getItem('orbita-v1'))||initial();if(!Array.isArray(state.agents)||!state.agents.length||!Array.isArray(state.bookings))state=initial()}catch{state=initial()}
let cloud={mode:'loading',version:0,workspaceId:null,user:null,integrations:{sessions:[],payments:[]},queue:Promise.resolve(),pending:0,error:null,choices:{},chatTab:'preview',inbox:[],selectedConversation:null};
let page='home',catalogTab='offerings',offeringFilter='all',setupAgent=state.agents[0].id,agentFilter='all',agendaDate=today(),chatAgent=state.agents[0].id,chatMessages={},toastTimer;
function persistDemo(){try{localStorage.setItem('orbita-v1',JSON.stringify(state));return true}catch{toast('Não foi possível salvar neste navegador. Verifique o espaço disponível.');return false}}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),4300)}
const navItems=[['home','home','Visão geral'],['setup','check','Configuração'],['agenda','calendar','Agenda'],['chats','chat','Conversas'],['agents','bot','Agentes'],['gallery','gallery','Catálogo'],['menu','receipt','Cardápio / página'],['finance','wallet','Financeiro'],['plans','star','Meu plano'],['settings','settings','Ajustes']];
const badge=(text,color='')=>`<span class="badge ${color}"><i class="dot"></i>${esc(text)}</span>`;
const button=(text,action,primary=false,ic='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
function head(title,desc,action=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function note(t){return `<div class="note">${icon('info')}<div class="notetext">${t}</div></div>`}
function moneyDemo(){const done=state.bookings.filter(b=>b.status==='Concluído').reduce((n,b)=>n+b.price,0),received=done+state.entries.filter(e=>e.type==='income').reduce((n,e)=>n+e.amount,0),expense=state.entries.filter(e=>e.type==='expense').reduce((n,e)=>n+e.amount,0),pending=state.bookings.filter(b=>b.status==='Confirmado').reduce((n,b)=>n+b.price,0);return {received,expense,pending,net:received-expense}}
function metric(label,value,foot,ic='wallet'){return `<div class="metric"><div class="row between"><span>${label}</span>${icon(ic)}</div><div class="metric-value">${value}</div><small>${foot}</small></div>`}
function appearancePanel(){return '<section class="card section-gap"><div class="cardhead"><div><h2>Aparência</h2><p>'+ (appearance()==='light'?'Pérola · branco com reflexos de verde e azul':'Escuro · Órbita')+'</p></div>'+button(appearance()==='light'?'Usar modo escuro':'Usar modo pérola','appearance')+'</div><p class="footnote">Sua preferência fica salva neste dispositivo.</p></section>';}
function appearance(){try{const saved=localStorage.getItem('orbita-appearance');if(['light','dark'].includes(saved))return saved;}catch{}return state.theme==='light'?'light':'dark';}
async function signOutCloud(){if(cloud.leaving)return;if(cloud.sending||cloud.menuBusy||cloud.replySending)return toast('Aguarde a operação em andamento antes de sair.');await cloud.queue;if(cloud.menuDirty||cloud.error){modal('Sair com alterações pendentes?','<p>Existem alterações que ainda não foram salvas. Ao sair, esses ajustes podem ser perdidos.</p><div class="modalfoot"><button class="btn" data-close>Continuar no app</button><button class="btn primary" id="leave-unsaved">Sair mesmo assim</button></div>');document.querySelector('#leave-unsaved').onclick=()=>finishSignOut();return;}return finishSignOut();}
async function finishSignOut(){if(cloud.leaving)return;cloud.leaving=true;try{if(cloud.user?.authProvider==='google'){const response=await fetch('/auth/logout',{method:'POST',credentials:'same-origin',signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error('Não foi possível sair. Tente novamente.');location.assign('/login?signed_out=1');}else location.assign('/signout-with-chatgpt?return_to=%2F');}catch(e){cloud.leaving=false;toast(e.message||'Não foi possível sair. Confira sua conexão.');}}
function renderBase(){document.body.classList.toggle('light',appearance()==='light');document.querySelector('meta[name="theme-color"]')?.setAttribute('content',appearance()==='light'?'#f1f6f3':'#0d0c14');const active=navItems.find(n=>n[0]===page);document.querySelector('#app').innerHTML=`<aside class="sidebar"><div class="brand">${icon('orbit')}<span>órbita<span style="color:var(--accent)">.</span></span></div><div class="workspace"><div class="avatar">${icon('orbit')}</div><div><strong>Minha empresa</strong><small>Seu espaço de demonstração</small></div></div><div class="navlabel">SEU NEGÓCIO</div><nav class="nav" aria-label="Navegação principal">${navItems.map(([id,ic,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="sidebottom"><div class="planmini"><div class="row between"><strong>Plano Equipe</strong>${icon('spark')}</div><div class="progress"><span style="width:${state.agents.length*25}%"></span></div><small>${state.agents.length} de 4 números configurados</small><button class="textbtn" data-page="plans">Conhecer o plano ${icon('arrow')}</button></div><div class="owner"><div class="avatar">P</div><div><strong>Pedro Alves</strong><small>Proprietário · demonstração</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">${icon('home')}<span>/</span><b>${active[2]}</b></div><div class="mobilebrand">${icon('orbit')}órbita.</div><div class="topactions"><span class="prototype">ESBOÇO · DADOS DEMO</span><button class="iconbtn appearance-toggle" data-action="appearance" aria-label="${appearance()==='light'?'Ativar modo escuro':'Ativar modo pérola'}" title="${appearance()==='light'?'Modo escuro':'Modo pérola'}">${icon(appearance()==='light'?'moon':'sun')}</button>${cloud.mode==='live'?'<button class="btn account-exit" data-action="logout">Sair</button>':''}<button class="iconbtn" data-action="help" aria-label="Sobre a Órbita">${icon('info')}</button></div></header><div class="content"><div class="page">${({home:home,setup:setup,agenda:agenda,chats:chats,agents:agents,gallery:gallery,menu:menuPage,finance:finance,plans:plans,settings:settings,growth:()=>globalThis.OrbitaGrowth?.view()||''}[page])()}</div></div></main>`;bind();}
function baseHome(){const m=money();return head('Tudo em sintonia, Pedro.','Um olhar sobre seu negócio. Mais tempo para cuidar de quem chega.',button('Novo agendamento','booking',true,'plus'))+`<section class="hero"><div><div class="hero-label">${icon('spark')}SEU ATENDIMENTO, EM ÓRBITA</div><h2>Você cuida do negócio.<br>A gente cuida das conversas.</h2><p>Uma equipe de agentes, cada um com seu jeito.<br>Conheça e personalize seus atendentes virtuais.</p></div><div class="orb">${icon('bot')}</div>${button('Conhecer meus agentes','go-agents',false,'arrow')}</section><div class="metrics">${metric('Recebido',cash(m.received),'Valores de demonstração','wallet')}${metric('A receber',cash(m.pending),'Reservas confirmadas · exemplo','receipt')}${metric('Resultado estimado',cash(m.net),'Recebido menos despesas registradas','home')}${metric('Agendamentos',state.bookings.filter(b=>b.status!=='Cancelado').length,'Reservas neste navegador','calendar')}</div><div class="grid2"><section class="card"><div class="cardhead"><div><h2>O ritmo do seu negócio</h2><p>Recebimentos ao longo da semana</p></div><span class="badge">Exemplo visual</span></div><div class="chart"><svg viewBox="0 0 620 160" preserveAspectRatio="none" role="img" aria-label="Curva ilustrativa de recebimentos, sem dados reais"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a793ff" stop-opacity=".25"/><stop offset="1" stop-color="#a793ff" stop-opacity="0"/></linearGradient></defs><g stroke="var(--line)" stroke-width="1" stroke-dasharray="3 6"><path d="M0 25H620M0 70H620M0 115H620M0 159H620"/></g><path d="M0 127C40 127 55 87 100 97S170 144 205 111 245 30 300 60 355 107 410 68 470 84 505 43 580 73 620 21V160H0Z" fill="url(#fill)"/><path d="M0 127C40 127 55 87 100 97S170 144 205 111 245 30 300 60 355 107 410 68 470 84 505 43 580 73 620 21" stroke="var(--accent)" stroke-width="2.5" fill="none"/><path d="M0 146C60 146 95 127 130 137S215 122 260 133 330 94 380 120 470 116 500 101 570 115 620 89" stroke="var(--muted)" stroke-opacity=".4" stroke-width="1.5" stroke-dasharray="5 5" fill="none"/></svg><div class="chart-labels"><span>SEG</span><span>TER</span><span>QUA</span><span>QUI</span><span>SEX</span><span>SÁB</span><span>DOM</span></div></div><div class="chartlegend"><span><i></i>Esta semana</span><span><i class="secondary"></i>Semana anterior</span></div></section><section class="card"><div class="cardhead"><div><h2>Sua equipe de agentes</h2><p>Uma personalidade para cada atendimento</p></div><button class="textbtn" data-page="agents">Ver todos ${icon('arrow')}</button></div><div class="agentsmini">${state.agents.map(a=>`<div class="agentmini"><div class="avatar">${esc(a.name.charAt(0))}</div><div><strong>${esc(a.name)}</strong><small>${esc(a.label)}</small></div>${badge(a.paused?'Pausado':'Demonstração',a.paused?'amber':'')}</div>`).join('')}</div></section></div><section class="card section-gap"><div class="cardhead"><div><h2>Próximos encontros</h2><p>A experiência começa antes do atendimento.</p></div><button class="textbtn" data-page="agenda">Abrir agenda ${icon('arrow')}</button></div>${bookingTable(state.bookings.filter(b=>b.status==='Confirmado'))}</section><p class="footnote">Ambiente de demonstração. Edições ficam neste navegador. WhatsApp, IA externa, login Google e Asaas ainda não estão conectados.</p>`}
function bookingTable(list,actions=false){return list.length?`<div class="tablewrap"><table class="table"><thead><tr><th>CLIENTE</th><th>SERVIÇO</th><th>PROFISSIONAL</th><th>HORÁRIO</th><th>STATUS</th>${actions?'<th>AÇÃO</th>':''}</tr></thead><tbody>${list.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(b=>`<tr><td><div class="client"><div class="avatar">${esc(b.client.split(' ').map(v=>v[0]).slice(0,2).join(''))}</div>${esc(b.client)}</div></td><td>${esc(b.service)}</td><td>${esc(b.professional)}</td><td>${esc(b.time)} <small>· ${dateLabel(b.date)}</small></td><td>${badge(b.status,b.status==='Concluído'?'green':b.status==='Cancelado'?'amber':'')}</td>${actions?`<td>${b.status==='Confirmado'?`<button class="textbtn" data-complete="${esc(b.id)}">Concluir</button><button class="textbtn" data-cancel="${esc(b.id)}">Cancelar</button>`:'—'}</td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum agendamento por aqui. Que tal criar o primeiro?</div>'}
function agenda(){return head('Agenda','Cada profissional, uma agenda. Todos os canais em sintonia.',button('Agendar','booking',true,'plus'))+`<div class="filterbar"><div class="tabs">${['all',...(state.professionals||['João','Lucas'])].map(x=>`<button data-filter="${esc(x)}" class="${agentFilter===x?'active':''}">${esc(x==='all'?'Toda a equipe':x)}</button>`).join('')}</div><div class="row"><label for="agenda-date" style="margin:0">Data</label><input id="agenda-date" type="date" value="${agendaDate}"></div></div><section class="card"><div class="agenda-day"><b>${new Date(agendaDate+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</b> · ${esc(state.hours.start)}–${esc(state.hours.end)} · intervalo ${esc(state.hours.lunchStart)}–${esc(state.hours.lunchEnd)}</div>${bookingTable(state.bookings.filter(b=>b.date===agendaDate&&(agentFilter==='all'||b.professional===agentFilter)),true)}</section><p class="footnote">${cloud.mode==='live'?'Reservas verificadas no servidor. Alterações concorrentes são bloqueadas para evitar horários duplicados.':'Demonstração local: as reservas ficam somente neste navegador.'}</p>`}
function agents(){return head('Seus agentes','Vários números. Personalidades únicas. Uma operação organizada.',button('Adicionar número','add-agent',true,'plus'))+note('Personalize cada agente e experimente o atendimento. Nenhum número está conectado ao WhatsApp nesta versão.')+`<div class="agentsgrid">${state.agents.map(a=>`<section class="card agentcard"><div class="row between"><div class="avatar">${esc(a.name.charAt(0))}</div>${badge(a.paused?'Pausado':a.demo===false?'Não conectado':'Demonstração',a.paused?'amber':'')}</div><h2>${esc(a.name)}</h2><p>${esc(a.label)}<br>${esc(a.phone)}</p><div class="infobox"><span class="muted">Personalidade</span><br>${esc(a.personality)}<br><span class="muted">Agenda:</span> ${esc(a.professional==='Todos'?'Toda a equipe':a.professional)}</div><div class="actions"><button class="btn" data-edit-agent="${esc(a.id)}">Personalizar</button><button class="btn" data-test-agent="${esc(a.id)}">${icon('chat')}Testar</button></div><button class="textbtn" style="margin-top:13px" data-pause-agent="${esc(a.id)}">${a.paused?'Retomar agente':'Pausar agente'}</button></section>`).join('')}${state.agents.length<4?`<button class="addcard" data-action="add-agent">${icon('plus')}<h3>Mais um número, mais possibilidades.</h3><p>${4-state.agents.length} vaga${4-state.agents.length>1?'s':''} no plano Equipe.<br>Um novo agente com o seu jeito.</p></button>`:''}</div><p class="footnote">Cada número terá uma sessão independente. Pausar um agente não altera os demais. O dono controla as permissões da equipe.</p>`}
function chatsDemo(){const a=state.agents.find(x=>x.id===chatAgent)||state.agents[0];chatAgent=a.id;const messages=chatMessages[a.id]||[{who:'agent',text:`Oi! Eu sou ${a.name}, assistente virtual da Barbearia Studio. Quer conhecer os serviços ou consultar horários?`}];return head('Conversas','Experimente a experiência que seus clientes vão encontrar.')+`<section class="card chatlayout"><aside class="chatlist">${state.agents.map(v=>`<button class="chatperson ${v.id===a.id?'active':''}" data-chat-agent="${esc(v.id)}"><div class="avatar">${esc(v.name.charAt(0))}</div><div><strong>${esc(v.name)} · ${esc(v.professional)}</strong><small>Simulador de atendimento</small></div></button>`).join('')}</aside><div class="chatmain"><div class="chathead"><div class="row"><div class="avatar">${esc(a.name.charAt(0))}</div><div><strong>${esc(a.name)}</strong><small>Simulação guiada · ${a.paused?'agente pausado':esc(a.personality)}</small></div></div><button class="btn" data-action="clear-chat">Limpar</button></div><div class="bubbles" aria-live="polite">${messages.map(m=>`<div class="bubble ${m.who==='client'?'own':''}"><small>${m.who==='client'?'Você, como cliente':esc(a.name)+' · simulador'}</small>${esc(m.text)}</div>`).join('')}</div><div class="quickchoices">${['Quais são os serviços?','Tem horário disponível?','Quero ver fotos'].map(t=>`<button data-say="${t}">${t}</button>`).join('')}</div><form class="chatinput" id="chat-form"><input name="message" required maxlength="500" placeholder="Converse com o simulador…" aria-label="Mensagem de teste"><button class="btn primary" aria-label="Enviar mensagem">${icon('send')}</button></form></div></section><p class="footnote">As opções clicáveis acima pertencem ao simulador do app. Elas não comprovam suporte a botões dentro do WhatsApp. Respostas guiadas, sem modelo de IA conectado.</p>`}
function financeDemo(){const m=money();return head('Financeiro','Entenda o que entrou, o que falta receber e o que saiu.',button('Lançar valor','entry',true,'plus'))+`<div class="metrics">${metric('Recebido',cash(m.received),'Lançamentos + serviços concluídos')}${metric('A receber',cash(m.pending),'Serviços confirmados')}${metric('Despesas',cash(m.expense),'Valores registrados')}${metric('Resultado estimado',cash(m.net),'Sem despesas não cadastradas')}</div><section class="card"><div class="cardhead"><h2>Movimentações</h2><span class="badge">Demonstração</span></div><div class="tablewrap"><table class="table"><thead><tr><th>DESCRIÇÃO</th><th>TIPO</th><th>VALOR</th></tr></thead><tbody>${state.entries.map(e=>`<tr><td>${esc(e.label)}</td><td>${e.type==='income'?'Entrada':'Despesa'}</td><td class="${e.type==='income'?'moneypositive':'moneynegative'}">${e.type==='income'?'+':'−'} ${cash(e.amount)}</td></tr>`).join('')}${state.bookings.filter(b=>b.status==='Concluído').map(b=>`<tr><td>${esc(b.client)} · ${esc(b.service)}</td><td>Serviço concluído · demo</td><td class="moneypositive">+ ${cash(b.price)}</td></tr>`).join('')}</tbody></table></div></section><p class="footnote">Nesta demonstração, concluir um serviço registra seu valor como recebido. Na versão integrada, realização do serviço e pagamento terão estados separados. Asaas não conectado.</p>`}
function plans(){const billing=cloud.billing,plans=billing?.plans||[],request=billing?.request;return head('Escolha sua órbita.','Mensalidade fixa, franquia clara e atendimento com o seu jeito.')+(request?note(request.status==='ACTIVE'?'Seu plano está ativo.':'Solicitação registrada. A equipe vai confirmar o pagamento e a ativação. Nenhuma cobrança foi criada.'):'')+`<div class="agentsgrid">${plans.map((p,i)=>`<section class="card agentcard ${i===1?'planfeatured':''}"><div class="row between"><h2>${esc(p.name)}</h2>${i===1?'<span class="badge">Mais escolhido</span>':''}</div><p>${esc(p.description)}</p><div class="planprice">${cash(p.price/100)}<small> / mês</small></div><div class="planfeatures">${[p.responses.toLocaleString('pt-BR')+' respostas de IA por mês',p.numbers+' número(s) de WhatsApp','Agenda e catálogo','Agente personalizável','Cardápio virtual por PDF'].map(t=>`<span>${icon('check')}${esc(t)}</span>`).join('')}</div><button class="btn ${i===1?'primary':''}" data-plan-request="${p.id}" ${request?.status==='ACTIVE'?'disabled':''}>${request?.status==='ACTIVE'?(request.plan_id===p.id?'Seu plano atual':'Fale com a equipe para alterar'):request?.plan_id===p.id?'Ver solicitação':'Solicitar ativação'}</button></section>`).join('')}</div><p class="footnote">Sem taxa de implantação. As respostas são compartilhadas entre os números do plano. Mensagens recebidas não são respostas de IA. Ao atingir a franquia, o atendimento humano continua disponível; não há cobrança automática de excedentes. Números adicionais dependem de conector compatível, preparado na ativação.</p><p class="footnote">A ativação é acompanhada pela equipe. O piloto atual usa infraestrutura de teste; o plano comercial só deve ser ativado depois de validar a conexão e o pagamento.</p>${cloud.features?.ownerGrowth?'<button class="btn" id="plan-requests">Gerenciar solicitações de planos</button>':''}`;}
function requestPlanForm(id){const p=cloud.billing?.plans?.find(p=>p.id===id);if(!p)return;modal('Ativar plano '+esc(p.name),`<form><p>${cash(p.price/100)} por mês · ${p.responses.toLocaleString('pt-BR')} respostas · ${p.numbers} número(s).</p><p>A solicitação será registrada para a equipe preparar a conexão e orientar o pagamento. Não haverá cobrança automática.</p><label class="field"><span><input type="checkbox" name="confirm" required style="width:auto"> Confirmo o plano e quero solicitar a ativação.</span></label><div class="formerror" role="alert"></div><div class="modalfoot"><button type="button" class="btn" data-close>Voltar</button><button class="btn primary">Registrar solicitação</button></div></form>`,async(f,form)=>{const button=form.querySelector('.primary');button.disabled=true;button.textContent='Registrando…';try{const result=await api('/billing',{method:'POST',body:{planId:id,confirm:f.get('confirm')==='on'}});cloud.billing=result.billing;document.querySelector('#modal').close();render();toast(result.message);}catch(e){error(form,e.message);}finally{button.disabled=false;button.textContent='Registrar solicitação';}});}
async function planRequests(){try{const r=await api('/billing/requests');modal('Solicitações de planos',r.requests.map(v=>`<article class="card"><strong>${esc(v.companyName)}</strong><p>${esc(cloud.billing.plans.find(p=>p.id===v.plan_id)?.name||v.plan_id)} · ${cash(v.price/100)}/mês · ${v.status==='ACTIVE'?'Ativo':'Aguardando ativação'}</p>${v.status==='REQUESTED'?`<button class="btn" data-activate-plan="${esc(v.workspace_id)}">Conferir ativação</button>`:''}</article>`).join('')||'<p>Nenhuma solicitação por enquanto.</p>');document.querySelectorAll('[data-activate-plan]').forEach(b=>b.onclick=()=>{const id=b.dataset.activatePlan;modal('Confirmar ativação comercial',`<form><p>Ative somente depois de verificar o pagamento e preparar o conector para todos os números contratados. Esta ação libera a franquia; não gera cobranças.</p><label><input name="confirm" type="checkbox" required style="width:auto"> Pagamento confirmado e conexão preparada.</label><div class="formerror" role="alert"></div><div class="modalfoot"><button type="button" class="btn" data-close>Voltar</button><button class="btn primary">Ativar plano</button></div></form>`,async(f,form)=>{try{await api('/billing/requests',{method:'POST',body:{workspaceId:id,paymentConfirmed:f.get('confirm')==='on'}});document.querySelector('#modal').close();await reloadCloud();}catch(e){error(form,e.message);}});});}catch(e){toast(e.message);}}

function settingsDemo(){return head('Tudo do seu jeito.','Conexões e preferências da sua operação.')+`<div class="integrations"><section class="card integration"><div class="row between"><div class="row">${icon('phone')}<h2>WhatsApp</h2></div>${badge('Não conectado','amber')}</div><p>WAHA é o candidato inicial. Conexão por código, sessões independentes e acompanhamento de cada número.</p>${button('Ver conexões','go-agents',false,'arrow')}</section><section class="card integration"><div class="row between"><div class="row">${icon('wallet')}<h2>Asaas</h2></div>${badge('Não conectado','amber')}</div><p>Recebimentos, cobranças e confirmação de pagamentos. A integração será configurada no servidor.</p>${button('O que falta conectar?','integration-info',false,'info')}</section></div><section class="card section-gap"><div class="cardhead"><h2>Preferências</h2></div><div class="settinglist"><div class="settingrow"><div>Plano e números<small>${state.agents.length} de 4 configurações neste esboço</small></div><button class="textbtn" data-page="plans">Ver planos ${icon('arrow')}</button></div><div class="settingrow"><div>Dados de demonstração<small>Restaurar apenas os dados deste navegador.</small></div>${button('Restaurar','reset')}</div></div></section><p class="footnote">Login Google, banco compartilhado e credenciais de integrações ainda serão implementados. Este link tem acesso privado de revisão.</p>`}
function modal(title,html,onSubmit){const d=document.querySelector('#modal');d.innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="iconbtn" id="close-modal" aria-label="Fechar">${icon('close')}</button></div><div class="modalbody">${html}</div>`;d.showModal();document.querySelector('#close-modal').onclick=()=>d.close();d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());if(onSubmit)d.querySelector('form').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.target),e.target)};}
function error(form,t){form.querySelector('.formerror').textContent=t}
function agentForm(id){const a=id?state.agents.find(x=>x.id===id):{label:'',name:'',personality:'Acolhedora e objetiva',professional:'Todos',phone:''};if(!id&&state.agents.length>=(cloud.billing?.request?.status==='ACTIVE'?cloud.billing.plans.find(p=>p.id===cloud.billing.request.plan_id)?.numbers||1:4))return toast('Seu plano comporta até quatro números.');modal(id?'Personalizar agente':'Adicionar número',`<form><div class="field"><label for="alabel">Nome desta conexão</label><input id="alabel" name="label" value="${esc(a.label)}" placeholder="Ex.: Marina · Barbeira" required maxlength="50"></div><div class="fieldrow"><div class="field"><label for="aname">Nome do agente</label><input id="aname" name="name" value="${esc(a.name)}" placeholder="Ex.: Luna" required maxlength="30"></div><div class="field"><label for="aprof">Quem pode agendar?</label><select id="aprof" name="professional">${['Todos',...(state.professionals||['João','Lucas'])].map(x=>`<option ${a.professional===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div><div class="field"><label for="aphone">Número WhatsApp com DDI</label><input id="aphone" name="phone" type="tel" value="${a.phone==='Número de demonstração'?'':esc(a.phone)}" placeholder="+55 44 99999-9999" maxlength="24" ${id?'':'required'}></div><div class="field"><label for="apersonality">Personalidade</label><textarea id="apersonality" name="personality" required maxlength="350">${esc(a.personality)}</textarea></div><small>${cloud.mode==='live'?'Configuração salva na sua conta. O pareamento é feito separadamente na aba Agentes.':'Salva a configuração local. Pareamento real e código ainda não estão disponíveis.'}</small><div class="formerror" role="alert"></div><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Salvar configuração</button></div></form>`,(f,form)=>{const phone=String(f.get('phone')).trim(),digits=phone.replace(/\D/g,'');if(phone&&(digits.length<10||digits.length>15))return error(form,'Informe um número válido com DDI.');if(phone&&state.agents.some(x=>x.id!==id&&x.phone.replace(/\D/g,'')===digits))return error(form,'Esse número já está cadastrado.');const data={label:f.get('label').trim(),name:f.get('name').trim(),personality:f.get('personality').trim(),professional:f.get('professional'),phone:phone||a.phone};if(!data.name||!data.label||!data.personality)return error(form,'Preencha os campos sem usar apenas espaços.');if(id){Object.assign(a,data);state.agentSetup[id]={...(state.agentSetup[id]||{}),name:true,personality:true};}else{const agentId=uid();state.agents.push({...data,id:agentId,demo:false,paused:false});state.agentSetup[agentId]={name:true,personality:true};}persist();document.querySelector('#modal').close();render();toast(cloud.mode==='live'?'Configuração enviada para salvar.':'Configuração salva neste navegador.');});}
function albumDemo(id){const g=state.gallery.find(x=>x.id===id);modal(esc(g.title),`<p class="muted" style="font-size:12px;line-height:1.8;margin-bottom:18px">${esc(g.desc)}</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${g.media.map((m,i)=>`<div><img src="${esc(m.url)}" alt="${esc(g.title)} · foto ${i+1}" style="width:100%;height:140px;object-fit:cover;border-radius:8px"><small>${i===0?'Capa':'Foto '+(i+1)}</small></div>`).join('')}</div>${g.media.length?'':'<div class="empty">Este álbum ainda não tem fotos.</div>'}<div class="field" style="margin-top:20px"><label for="upload">Adicionar foto (JPG, PNG ou WebP · até 700 KB)</label><input id="upload" type="file" accept="image/jpeg,image/png,image/webp"></div><small>Até 4 fotos por item neste esboço. Vídeos e armazenamento em nuvem entram na integração.</small>`);document.querySelector('#upload').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(g.media.length>=4)return toast('Limite de quatro fotos neste esboço.');if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>700*1024)return toast('Use JPG, PNG ou WebP com até 700 KB.');const reader=new FileReader();reader.onload=()=>{g.media.push({url:reader.result,name:f.name});if(!persist()){g.media.pop();return}document.querySelector('#modal').close();render();album(id);};reader.readAsDataURL(f);};}
function bindBase(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(b.dataset.setupAgent)setupAgent=b.dataset.setupAgent;navigateTo(b.dataset.page)});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-edit-agent]').forEach(b=>b.onclick=()=>agentForm(b.dataset.editAgent));document.querySelectorAll('[data-test-agent],[data-chat-agent]').forEach(b=>b.onclick=()=>{navigateTo('chats',{chatTab:'preview',agentId:b.dataset.testAgent||b.dataset.chatAgent})});document.querySelectorAll('[data-pause-agent]').forEach(b=>b.onclick=()=>{const a=state.agents.find(v=>v.id===b.dataset.pauseAgent);a.paused=!a.paused;persist();render();toast(a.paused?'Agente pausado. Os outros continuam como estavam.':'Agente retomado no simulador.')});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{agentFilter=b.dataset.filter;render()});document.querySelector('#agenda-date')?.addEventListener('change',e=>{if(e.target.value){agendaDate=e.target.value||today();render()}});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{const item=state.bookings.find(x=>x.id===b.dataset.cancel);modal('Cancelar agendamento?',`<p style="line-height:1.8">A reserva de ${esc(item.client)}, às ${esc(item.time)}, será cancelada neste navegador.</p><div class="modalfoot"><button class="btn" data-close>Manter reserva</button><button class="btn primary" id="confirm-cancel">Cancelar reserva</button></div>`);document.querySelector('#confirm-cancel').onclick=()=>{item.status='Cancelado';persist();document.querySelector('#modal').close();render();toast('Reserva cancelada. Horário liberado.')}});document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{state.bookings.find(x=>x.id===b.dataset.complete).status='Concluído';persist();render();toast('Serviço concluído nesta demonstração.')});document.querySelectorAll('[data-album]').forEach(b=>b.onclick=()=>album(b.dataset.album));document.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>say(b.dataset.say));document.querySelector('#chat-form')?.addEventListener('submit',e=>{e.preventDefault();const t=new FormData(e.target).get('message').trim();if(t)say(t)});document.querySelectorAll('[data-plan-info]').forEach(b=>b.onclick=()=>modal('Plano '+esc(b.dataset.planInfo),'<p style="font-size:13px;line-height:1.9">Esta é uma proposta de plano. Contratação, checkout e cobrança ainda não foram ativados. No plano Equipe, os quatro números terão uma franquia compartilhada, com consumo por agente visível para o dono.</p>'));}
function legacyAction(a){if(a==='booking')bookingForm();else if(a==='go-agents'){navigateTo('agents')}else if(a==='add-agent')agentForm();else if(a==='clear-chat'){delete chatMessages[chatAgent];render()}else if(a==='help')modal('Sobre a Órbita',`<p style="font-size:13px;line-height:1.9">Este é o primeiro desenho interativo da Órbita, nome provisório do seu app.<br><br>Você pode personalizar agentes, testar conversas guiadas, criar reservas locais, montar álbuns e registrar valores.<br><br>Os dados são de demonstração e ficam apenas neste navegador. Conexões reais de WhatsApp, IA, Google e Asaas ainda não estão ativadas.</p>`);else if(a==='integration-info')modal('Próxima etapa das integrações','<p style="font-size:13px;line-height:1.9">Precisamos de um servidor WAHA acessível, números autorizados para pareamento e ambiente Asaas de testes. As chaves serão armazenadas no servidor.<br><br>Não cole senhas ou chaves neste esboço. Ele ainda não tem armazenamento seguro de credenciais.</p>');else if(a==='reset'){modal('Restaurar demonstração?',`<p style="line-height:1.8">Isso apaga as personalizações e fotos salvas por este esboço neste navegador.</p><div class="modalfoot"><button class="btn" data-close>Manter meus dados</button><button class="btn primary" id="confirm-reset">Restaurar</button></div>`);document.querySelector('#confirm-reset').onclick=()=>{const theme=state.theme;state=initial();state.theme=theme;initializeV2();chatMessages={};chatAgent='central';persist();document.querySelector('#modal').close();render();toast('Demonstração restaurada.')}}else if(a==='entry'){modal('Lançar valor',`<form><div class="field"><label for="elabel">Descrição</label><input name="label" id="elabel" required maxlength="100"></div><div class="fieldrow"><div class="field"><label for="etype">Tipo</label><select name="type" id="etype"><option value="income">Entrada</option><option value="expense">Despesa</option></select></div><div class="field"><label for="eamount">Valor (R$)</label><input id="eamount" name="amount" type="number" min="0.01" step="0.01" required></div></div><div class="formerror" role="alert"></div><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Salvar lançamento</button></div></form>`,(f,form)=>{if(!f.get('label').trim())return error(form,'Informe a descrição.');state.entries.push({id:uid(),label:f.get('label').trim(),amount:Number(f.get('amount')),type:f.get('type')});persist();document.querySelector('#modal').close();render();toast(cloud.mode==='live'?'Lançamento enviado para salvar.':'Lançamento salvo neste navegador.')});}}
function initializeV2(){
 state.agentSetup=state.agentSetup||{};
 state.hours=state.hours||{start:'09:00',end:'19:00',lunchStart:'12:00',lunchEnd:'13:00',days:[1,2,3,4,5,6]};
 state.paymentMode=state.paymentMode||'online';
 if(!state.offerings){state.offerings=[{id:'cut',title:'Corte masculino',desc:'Corte personalizado com acabamento e finalização.',price:45,duration:30,kind:'service',active:true,albumId:''},{id:'combo',title:'Corte + barba',desc:'Corte e barba no mesmo atendimento.',price:75,duration:60,kind:'service',active:true,albumId:''}];state.gallery=state.gallery.filter(g=>g.media?.length||!['g1','g2','g3'].includes(g.id));}
}
initializeV2();
function demoConfigurationSteps(id=setupAgent){const a=state.agents.find(v=>v.id===id)||state.agents[0],saved=state.agentSetup[a.id]||{};return [
 {id:'name',title:'Dar um nome ao agente',desc:saved.name?a.name:'Como ele vai se apresentar?',done:!!saved.name,action:'agent',icon:'bot'},
 {id:'personality',title:'Definir a personalidade',desc:saved.personality?a.personality:'Tom, jeito de falar e orientações.',done:!!saved.personality,action:'agent',icon:'spark'},
 {id:'catalog',title:'Revisar serviços e produtos',desc:state.catalogConfirmed?'Catálogo revisado e salvo.':'Preços, duração e opções de escolha.',done:!!state.catalogConfirmed&&state.offerings.some(o=>o.active),action:'catalog',icon:'receipt'},
 {id:'hours',title:'Configurar o expediente',desc:state.hoursConfirmed?`${state.hours.start}–${state.hours.end} · ${state.hours.days.length} dias por semana`:'Dias de atendimento e pausas.',done:!!state.hoursConfirmed,action:'hours',icon:'calendar'},
 {id:'whatsapp',title:'Conectar o WhatsApp',desc:'Pendente de integração e pareamento real.',done:false,action:'whatsapp',icon:'phone',blocked:true},
 {id:'payment',title:state.paymentMode==='onsite'?'Pagamento presencial definido':'Configurar recebimentos',desc:state.paymentMode==='onsite'?'Cobrança online desativada.':'Asaas selecionado · conexão pendente.',done:state.paymentMode==='onsite',action:'payment',icon:'wallet',blocked:state.paymentMode!=='onsite'},
 {id:'test',title:'Testar conversa no simulador',desc:saved.tested?'Conversa guiada experimentada.':'Veja como nome e catálogo aparecem.',done:!!saved.tested,action:'test',icon:'chat'}];}
function progressInfo(id){const steps=configurationSteps(id),done=steps.filter(s=>s.done).length;return {steps,done,total:steps.length,percent:Math.round(done/steps.length*100)}}
function setupSummary(){const a=state.agents.find(a=>{const p=progressInfo(a.id);return p.done<p.total});if(!a)return '';const p=progressInfo(a.id);return `<section class="setup-summary"><div class="setup-dial" style="--pct:${p.percent}%"><span>${p.percent}<small>%</small></span></div><div class="setup-summary-text"><div class="hero-label">PRIMEIROS PASSOS</div><h2>Seu agente está ganhando forma.</h2><p>${p.done} de ${p.total} etapas concluídas · ${esc(a.name)}<br>Veja o que falta para preparar o atendimento.</p></div><button class="btn primary" data-page="setup" data-setup-agent="${esc(a.id)}">Continuar configuração ${icon('arrow')}</button></section>`}
function homeV2(){const html=baseHome(),pos=html.indexOf('<section class="hero">');return html.slice(0,pos)+setupSummary()+html.slice(pos)}
function setup(){const a=state.agents.find(x=>x.id===setupAgent)||state.agents[0];setupAgent=a.id;const p=progressInfo(a.id);return head('Um passo de cada vez.','Prepare seu agente e acompanhe o que ainda falta.')+`<div class="filterbar"><div class="row"><label for="setup-agent" style="margin:0;white-space:nowrap">Configurar agente</label><select id="setup-agent">${state.agents.map(x=>`<option value="${esc(x.id)}" ${a.id===x.id?'selected':''}>${esc(x.name)} · ${esc(x.label)}</option>`).join('')}</select></div>${badge(cloud.mode==='live'?'Configuração da empresa':'Configuração do esboço')}</div>${p.done===p.total?`<section class="card setup-overview"><div><div class="hero-label">${icon('check')} TUDO PRONTO</div><h2>Configuração concluída</h2><p>Você pode revisar e editar as configurações abaixo quando precisar.</p></div></section>`:`<section class="setup-overview card"><div><div class="hero-label">SEU PROGRESSO</div><h2>${p.done} de ${p.total} etapas concluídas</h2><p>Nome e personalidade são individuais. Catálogo, expediente e recebimentos pertencem à empresa.</p><div class="progress" role="progressbar" aria-label="Progresso de configuração" aria-valuenow="${p.percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${p.percent}%"></span></div></div><div class="setup-dial large" style="--pct:${p.percent}%"><span>${p.percent}<small>%</small></span></div></section>`}<div class="checklist-grid">${p.steps.map((s,i)=>`<button class="setup-step ${s.done?'done':''}" data-setup-step="${s.action}"><span class="step-icon">${icon(s.done?'check':s.icon)}</span><span class="step-copy"><strong>${i+1}. ${s.title}</strong><small>${esc(s.desc)}</small></span><span class="step-state">${s.done?'Concluído':s.blocked?'Pendente':'Configurar'} ${icon('chevron')}</span></button>`).join('')}</div><p class="footnote">${cloud.mode==='live'?'O progresso considera as configurações da empresa e integrações verificadas.':'O progresso é calculado pelas configurações salvas neste navegador. Dados de exemplo não concluem etapas.'} O teste no simulador não substitui um atendimento real no WhatsApp.</p>`}
function catalogTabs(){return `<div class="tabs"><button data-catalog-tab="offerings" class="${catalogTab==='offerings'?'active':''}">${icon('receipt')}Serviços e produtos</button><button data-catalog-tab="media" class="${catalogTab==='media'?'active':''}">${icon('gallery')}Mídias de apoio</button></div>`}
function gallery(){const isMedia=catalogTab==='media';return head('Seu catálogo, organizado.','O que o cliente escolhe e o que ajuda a explicar, cada um no seu lugar.',button(isMedia?'Novo álbum':'Novo serviço ou produto',isMedia?'add-media':'add-offering',true,'plus'))+`<div class="filterbar">${catalogTabs()}${!isMedia?`<div class="row"><span class="badge ${state.catalogConfirmed?'green':''}">${state.catalogConfirmed?'Catálogo revisado':'Revisão pendente'}</span><button class="btn" data-action="review-catalog">Revisar e confirmar</button></div>`:''}</div>`+(isMedia?mediaPage():offeringsPage());}
function offeringsPage(){const filtered=state.offerings.filter(o=>offeringFilter==='all'||o.kind===offeringFilter);return note('Cadastre aqui as opções que o cliente pode escolher: serviço com preço e duração ou produto com preço. Essas informações alimentam a agenda e o atendimento. Botões no WhatsApp dependem da integração do canal.')+`<div class="tabs compact">${[['all','Todos'],['service','Serviços'],['product','Produtos']].map(([v,t])=>`<button data-offering-filter="${v}" class="${offeringFilter===v?'active':''}">${t}</button>`).join('')}</div><div class="gallerygrid section-gap">${filtered.map(o=>`<section class="card offering-card"><div class="row between"><div class="avatar">${icon(o.kind==='service'?'scissors':'receipt')}</div>${badge(o.active?'Disponível':'Pausado',o.active?'green':'amber')}</div><small class="kind-label">${o.kind==='service'?'SERVIÇO':'PRODUTO'}</small><h2>${esc(o.title)}</h2><p>${esc(o.desc)}</p><div class="offering-price">${cash(o.price)}${o.kind==='service'?`<small>${icon('clock')}${o.duration} min</small>`:''}</div><div class="media-link">${icon('gallery')}<span>${o.albumId&&state.gallery.some(g=>g.id===o.albumId)?'Álbum de apoio vinculado':'Sem mídia de apoio vinculada'}</span></div><div class="row"><button class="btn" data-edit-offering="${esc(o.id)}">Editar</button><button class="textbtn" data-toggle-offering="${esc(o.id)}">${o.active?'Pausar opção':'Disponibilizar'}</button></div></section>`).join('')||'<div class="card empty">Nenhuma opção nesta categoria. Cadastre um serviço ou produto.</div>'}</div><p class="footnote">Serviços podem ser agendados; produtos são opções de catálogo. Criar um álbum não cria um serviço nem altera o preço. Os dados iniciais são exemplos editáveis.</p>`}
function mediaPage(){return note('Fotos e imagens de referência ficam em álbuns de apoio. Você pode vinculá-los a um serviço ou produto para o agente consultar e enviar quando o cliente pedir. Eles não viram opções de compra ou agendamento.')+`<div class="gallerygrid">${state.gallery.map(g=>{const linked=state.offerings.filter(o=>o.albumId===g.id);return `<section class="card"><div class="gallerycover">${g.media.length&&!g.media[0].type?.startsWith('video/')?`<img src="${esc(g.media[0].url)}" alt="${esc(g.title)}">`:icon('gallery')}<span class="badge" style="position:absolute;bottom:12px;left:12px">${g.media.length} arquivo(s)</span></div><div class="gallerybody"><h2>${esc(g.title)}</h2><p>${esc(g.desc)}</p><small>${linked.length?'Apoia: '+linked.map(o=>esc(o.title)).join(', '):'Referência geral · sem vínculo'}</small><div class="row between" style="margin-top:16px"><button class="textbtn" data-album="${esc(g.id)}">Abrir álbum ${icon('arrow')}</button><button class="textbtn" data-edit-media="${esc(g.id)}">Editar vínculo</button></div></div></section>`}).join('')||`<section class="card media-empty"><div class="avatar">${icon('gallery')}</div><h2>Suas referências ficam aqui.</h2><p>Crie um álbum com exemplos de cortes, detalhes de um produto ou imagens que ajudem o agente a explicar.</p><button class="btn primary" data-action="add-media">${icon('plus')}Criar primeiro álbum</button></section>`}</div><p class="footnote">Fotos locais neste esboço. Vídeos e envio de mídia pelo WhatsApp ainda dependem da integração.</p>`}
function offeringForm(id){const o=id?state.offerings.find(x=>x.id===id):{title:'',desc:'',price:0,duration:30,kind:['sushi','restaurante','lanchonete'].includes(state.businessTheme)?'product':'service',albumId:''};modal(id?'Editar opção do catálogo':'Novo serviço ou produto',`<form><div class="field"><label for="otype">Tipo de opção</label><select id="otype" name="kind"><option value="service" ${o.kind==='service'?'selected':''}>Serviço · pode ser agendado</option><option value="product" ${o.kind==='product'?'selected':''}>Produto · opção do catálogo</option></select></div><div class="field"><label for="otitle">Nome que o cliente vai escolher</label><input id="otitle" name="title" required maxlength="70" value="${esc(o.title)}" placeholder="Ex.: Corte masculino"></div><div class="field"><label for="odesc">Descrição</label><textarea id="odesc" name="desc" required maxlength="500">${esc(o.desc)}</textarea></div><div class="fieldrow"><div class="field"><label for="oprice">Preço fixo (R$)</label><input id="oprice" name="price" type="number" min="0" step="0.01" required value="${o.price}"></div><div class="field" id="duration-field" ${o.kind==='product'?'hidden':''}><label for="oduration">Duração (minutos)</label><input id="oduration" name="duration" type="number" min="5" max="600" step="5" value="${o.duration||30}" ${o.kind==='service'?'required':'disabled'}></div></div><div class="field"><label for="oalbum">Mídia de apoio (opcional)</label><select id="oalbum" name="albumId"><option value="">Sem álbum vinculado</option>${state.gallery.map(g=>`<option value="${esc(g.id)}" ${o.albumId===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></div><div class="formerror" role="alert"></div><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Salvar opção</button></div></form>`,(f,form)=>{const data={title:f.get('title').trim(),desc:f.get('desc').trim(),kind:f.get('kind'),price:Number(f.get('price')),duration:f.get('kind')==='service'?Number(f.get('duration')):0,albumId:f.get('albumId')};if(!data.title||!data.desc||!Number.isFinite(data.price)||data.price<0)return error(form,'Confira o nome, a descrição e o preço.');if(data.kind==='service'&&(!Number.isFinite(data.duration)||data.duration<5||data.duration>600))return error(form,'Informe uma duração entre 5 e 600 minutos.');if(id)Object.assign(o,data);else state.offerings.push({...data,id:uid(),active:true});state.catalogConfirmed=false;persist();document.querySelector('#modal').close();render();toast('Opção salva. Revise o catálogo para concluir essa etapa.');});document.querySelector('#otype').onchange=e=>{const isService=e.target.value==='service';document.querySelector('#duration-field').hidden=!isService;const d=document.querySelector('#oduration');d.disabled=!isService;d.required=isService;};}
function mediaForm(id){const g=id?state.gallery.find(x=>x.id===id):{title:'',desc:'',media:[]};const linked=state.offerings.find(o=>o.albumId===id);modal(id?'Editar álbum de apoio':'Novo álbum de apoio',`<form><div class="field"><label for="mtitle">Nome do álbum</label><input id="mtitle" name="title" required maxlength="70" value="${esc(g.title)}" placeholder="Ex.: Referências de corte degradê"></div><div class="field"><label for="mdesc">Como o agente deve usar essas imagens?</label><textarea id="mdesc" name="desc" required maxlength="500" placeholder="Ex.: Mostrar quando o cliente pedir exemplos do acabamento.">${esc(g.desc)}</textarea></div><div class="field"><label for="mlink">Vincular a um serviço ou produto (opcional)</label><select id="mlink" name="offering"><option value="">Referência geral</option>${state.offerings.map(o=>`<option value="${esc(o.id)}" ${linked?.id===o.id?'selected':''}>${esc(o.title)}</option>`).join('')}</select></div><small>Álbum sem preço. Ele auxilia o atendimento e não aparece como opção de serviço.</small><div class="formerror" role="alert"></div><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Salvar álbum</button></div></form>`,(f,form)=>{const title=f.get('title').trim(),desc=f.get('desc').trim();if(!title||!desc)return error(form,'Preencha nome e orientação do álbum.');const mediaId=id||uid();if(id)Object.assign(g,{title,desc});else state.gallery.push({id:mediaId,title,desc,type:'gallery',price:0,media:[]});state.offerings.forEach(o=>{if(o.albumId===mediaId)o.albumId='';});const o=state.offerings.find(v=>v.id===f.get('offering'));if(o)o.albumId=mediaId;persist();document.querySelector('#modal').close();render();if(!id)album(mediaId);else toast('Álbum e vínculo atualizados.');});}
function hoursForm(){const h=state.hours;modal('Expediente da empresa',`<form><div class="fieldrow"><div class="field"><label for="hstart">Abertura</label><input id="hstart" name="start" type="time" value="${h.start}" required></div><div class="field"><label for="hend">Encerramento</label><input id="hend" name="end" type="time" value="${h.end}" required></div></div><div class="fieldrow"><div class="field"><label for="hlstart">Início da pausa</label><input id="hlstart" name="lunchStart" type="time" value="${h.lunchStart}" required></div><div class="field"><label for="hlend">Fim da pausa</label><input id="hlend" name="lunchEnd" type="time" value="${h.lunchEnd}" required></div></div><label>Dias de atendimento</label><div class="weekday-options">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((n,i)=>`<label><input type="checkbox" name="days" value="${i}" ${h.days.includes(i)?'checked':''}>${n}</label>`).join('')}</div><small>Expediente compartilhado neste esboço. Exceções individuais entram em uma próxima etapa.</small><div class="formerror" role="alert"></div><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Salvar expediente</button></div></form>`,(f,form)=>{const v=Object.fromEntries(['start','end','lunchStart','lunchEnd'].map(k=>[k,f.get(k)]));v.days=f.getAll('days').map(Number);if(!v.days.length||!(v.start<v.lunchStart&&v.lunchStart<v.lunchEnd&&v.lunchEnd<v.end))return error(form,'Escolha ao menos um dia e mantenha abertura → pausa → retorno → encerramento em ordem.');state.hours=v;state.hoursConfirmed=true;persist();document.querySelector('#modal').close();render();toast('Expediente salvo e aplicado às novas reservas.');});}
function paymentForm(){modal('Como a empresa recebe?',`<form><div class="field"><label for="payment-mode">Forma de recebimento</label><select name="mode" id="payment-mode"><option value="online" ${state.paymentMode==='online'?'selected':''}>Cobrança online pelo Asaas · integração pendente</option><option value="onsite" ${state.paymentMode==='onsite'?'selected':''}>Somente presencial · sem cobrança online</option></select></div><div class="payment-provider"><div class="row between"><strong>Asaas</strong>${badge('Não conectado','amber')}</div><p>O Asaas pode gerar cobranças diretamente. Uma integração com Pagar.me não é uma etapa obrigatória deste fluxo.</p></div><small>Nenhuma chave é solicitada neste esboço. A conexão e a confirmação de recebimentos serão feitas pelo servidor. Pagar.me pode ser avaliado separadamente.</small><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Salvar preferência</button></div></form>`,f=>{state.paymentMode=f.get('mode');persist();document.querySelector('#modal').close();render();toast(state.paymentMode==='online'?'Preferência salva. Conectar Asaas continua pendente.':'Pagamento presencial definido, sem cobrança online.');});}
function bookingForm(){const services=state.offerings.filter(o=>o.active&&o.kind==='service');if(!services.length){toast('Cadastre e ative um serviço antes de agendar.');catalogTab='offerings';navigateTo('gallery');return}modal('Novo agendamento',`<form><div class="field"><label for="bclient">Nome do cliente</label><input id="bclient" name="client" required maxlength="70" placeholder="Nome e sobrenome"></div><div class="fieldrow"><div class="field"><label for="bservice">Serviço</label><select id="bservice" name="service">${services.map(o=>`<option value="${esc(o.id)}">${esc(o.title)} · ${o.duration} min · ${cash(o.price)}</option>`).join('')}</select></div><div class="field"><label for="bprof">Profissional</label><select id="bprof" name="professional">${(state.professionals||['João','Lucas']).map(p=>`<option>${esc(p)}</option>`).join('')}</select></div></div><div class="fieldrow"><div class="field"><label for="bdate">Data</label><input id="bdate" type="date" name="date" value="${agendaDate}" min="${today()}" required></div><div class="field"><label for="btime">Horário</label><input id="btime" type="time" name="time" value="16:00" step="300" required></div></div><div class="field"><label for="bchannel">Número de origem</label><select name="channel" id="bchannel">${state.agents.map(a=>`<option value="${esc(a.id)}">${esc(a.label)}</option>`).join('')}</select></div><small>Somente serviços ativos aparecem aqui. Produtos e mídias de apoio não são horários de agenda.</small><div class="formerror" role="alert"></div><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">${cloud.mode==='live'?'Confirmar reserva':'Confirmar reserva local'}</button></div></form>`,(f,form)=>{try{const o=state.offerings.find(x=>x.id===f.get('service')&&x.active&&x.kind==='service');if(!o)throw Error('Este serviço não está mais disponível.');const b={id:uid(),client:f.get('client').trim(),professional:f.get('professional'),date:f.get('date'),time:f.get('time'),channel:f.get('channel'),service:o.title,serviceId:o.id,duration:o.duration,price:o.price,status:'Confirmado'};if(b.date<today())throw Error('Escolha uma data atual ou futura.');const a=state.agents.find(x=>x.id===b.channel);if(a.professional!=='Todos'&&a.professional!==b.professional)throw Error('Este número atende apenas '+a.professional+'. Escolha a central ou o profissional correto.');OrbitaCore.validateBooking(state.bookings,b,state.hours);state.bookings.push(b);agendaDate=b.date;persist();document.querySelector('#modal').close();render();toast('Reserva enviada com preço e duração do catálogo.');}catch(e){error(form,e.message)}});}
function sayDemo(t){const a=state.agents.find(x=>x.id===chatAgent);if(a.paused)return toast('Agente pausado. Retome na aba Agentes para testar.');if(!chatMessages[a.id])chatMessages[a.id]=[{who:'agent',text:`Oi! Eu sou ${a.name}, assistente virtual da Barbearia Studio. Como posso ajudar?`}];chatMessages[a.id].push({who:'client',text:t});const options=state.offerings.filter(o=>o.active),q=t.toLowerCase();let reply;if(/foto|imagem|galeria|m[ií]dia/.test(q)){const linked=options.filter(o=>o.albumId&&state.gallery.some(g=>g.id===o.albumId&&g.media.length));reply=linked.length?'Temos fotos de apoio para: '+linked.map(o=>o.title).join(', ')+'. Você pode conferir os álbuns em Catálogo → Mídias de apoio. Neste simulador não envio imagens pelo WhatsApp.':'Ainda não há fotos de apoio vinculadas às opções disponíveis. Você pode adicionar um álbum em Catálogo → Mídias de apoio. O catálogo de serviços e preços continua separado.';}else if(/servi|preço|valor|corte|barba|produto/.test(q)){reply=options.length?'Estas são as opções disponíveis:\n'+options.map(o=>`• ${o.title} — ${cash(o.price)}${o.kind==='service'?` · ${o.duration} minutos`:''}`).join('\n'):'Ainda não há serviços ou produtos ativos no catálogo.';}else if(/hor|agend|dispon/.test(q)){const service=options.find(o=>o.kind==='service'),prof=a.professional==='Todos'?'João':a.professional;if(!service)reply='Ainda não há serviços disponíveis para agendamento. Produtos e fotos não ocupam horários na agenda.';else{const slots=[];for(let n=0;n<24*60;n+=30){const time=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');try{OrbitaCore.validateBooking(state.bookings,{client:'Teste',date:agendaDate,time,professional:prof,service:service.title,duration:service.duration},state.hours);slots.push(time)}catch{}}reply=`Para ${service.title} com ${prof}, em ${dateLabel(agendaDate)}, os horários livres de demonstração são: ${slots.slice(0,5).join(', ')||'nenhum horário'}.\nPara experimentar a reserva, abra Agenda → Agendar. Não fiz uma reserva nesta conversa.`;}}else if(/humano|rob[oô]|ia|virtual/.test(q))reply=`Sou ${a.name}, assistente virtual. Aqui você está usando um simulador guiado, ainda sem uma IA externa conectada.`;else reply='Posso mostrar serviços e produtos, consultar horários de serviços ou orientar sobre fotos de apoio. O que você quer ver primeiro?';chatMessages[a.id].push({who:'agent',text:reply});state.agentSetup[a.id]={...(state.agentSetup[a.id]||{}),tested:true};persist();render();const b=document.querySelector('.bubbles');b.scrollTop=b.scrollHeight;}
function bindV2(){bindBase();document.querySelector('#setup-agent')?.addEventListener('change',e=>{setupAgent=e.target.value;render()});document.querySelectorAll('[data-setup-step]').forEach(b=>b.onclick=()=>{const a=b.dataset.setupStep;if(a==='agent')agentForm(setupAgent);else if(a==='catalog'){catalogTab='offerings';navigateTo('gallery')}else if(a==='hours')hoursForm();else if(a==='payment')paymentForm();else if(a==='test'){navigateTo('chats',{chatTab:'preview',agentId:setupAgent})}else if(a==='whatsapp')modal('Conexão WhatsApp pendente','<p style="line-height:1.9;font-size:13px">O código de pareamento será gerado pela integração real, ainda não conectada. Seu número não será marcado como conectado só por ser cadastrado.<br><br>Próxima etapa: configurar o servidor do conector e parear um número autorizado.</p>');});document.querySelectorAll('[data-catalog-tab]').forEach(b=>b.onclick=()=>{catalogTab=b.dataset.catalogTab;render()});document.querySelectorAll('[data-offering-filter]').forEach(b=>b.onclick=()=>{offeringFilter=b.dataset.offeringFilter;render()});document.querySelectorAll('[data-edit-offering]').forEach(b=>b.onclick=()=>offeringForm(b.dataset.editOffering));document.querySelectorAll('[data-toggle-offering]').forEach(b=>b.onclick=()=>{const o=state.offerings.find(x=>x.id===b.dataset.toggleOffering);o.active=!o.active;state.catalogConfirmed=false;persist();render();toast(o.active?'Opção disponível no catálogo.':'Opção pausada para novos atendimentos.');});document.querySelectorAll('[data-edit-media]').forEach(b=>b.onclick=()=>mediaForm(b.dataset.editMedia));}
function actionV2(a){if(a==='add-offering')offeringForm();else if(a==='add-media')mediaForm();else if(a==='review-catalog'){modal('Revisar catálogo',`<p class="muted" style="font-size:12px;line-height:1.8;margin-bottom:15px">Confira as opções ativas que o agente vai oferecer. Fotos de apoio não aparecem como serviços.</p>${state.offerings.filter(o=>o.active).map(o=>`<div class="review-row"><span>${esc(o.title)}<small>${o.kind==='service'?o.duration+' min':'Produto'}</small></span><strong>${cash(o.price)}</strong></div>`).join('')||'<p>Nenhuma opção ativa.</p>'}<div class="modalfoot"><button class="btn" data-close>Voltar</button><button class="btn primary" id="confirm-catalog" ${state.offerings.some(o=>o.active)?'':'disabled'}>Confirmar catálogo revisado</button></div>`);document.querySelector('#confirm-catalog').onclick=()=>{state.catalogConfirmed=true;persist();document.querySelector('#modal').close();render();toast('Catálogo revisado. Progresso atualizado.');};}else if(a==='integration-info')paymentForm();else legacyAction(a);}
function persist(){if(cloud.mode==='demo')return persistDemo();if(cloud.mode!=='live')return false;if(cloud.error){toast('Há alterações não sincronizadas. Resolva a pendência antes de continuar.');return false;}const snapshot=JSON.parse(JSON.stringify(state));cloud.pending++;updateCloudBadge();cloud.queue=cloud.queue.then(async()=>{try{if(cloud.error)return;const r=await api('/state',{method:'PUT',body:{state:snapshot,version:cloud.version}});cloud.version=r.version;}catch(e){cloud.error=e.message;toast('Não salvo: '+e.message);}finally{cloud.pending--;updateCloudBadge();}});return true;}
let pendingRequests=0;
async function api(path,options={}){pendingRequests++;let indicator=document.querySelector('#request-progress');if(!indicator){indicator=document.createElement('div');indicator.id='request-progress';indicator.className='request-progress';indicator.setAttribute('role','status');indicator.setAttribute('aria-live','polite');indicator.textContent='Carregando…';document.body.append(indicator);}indicator.hidden=false;try{return await apiRequest(path,options);}finally{pendingRequests--;if(!pendingRequests)indicator.hidden=true;}}
async function apiRequest(path,options={}){const opts={...options,signal:options.signal||AbortSignal.timeout(30000),headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers}};if(options.body&&!(options.body instanceof FormData))opts.body=JSON.stringify(options.body);let r;try{r=await fetch('/api'+path,opts)}catch(e){throw Error(e.name==='TimeoutError'||e.name==='AbortError'?path.startsWith('/menus')?'A leitura demorou mais que o esperado. Seu PDF continua salvo. Atualize antes de tentar novamente.':'O servidor demorou para responder. Confira o status antes de repetir a operação.':'Sem comunicação com o servidor.');}let data;try{data=await r.json()}catch{throw Error('O servidor não retornou uma resposta válida.');}if(!r.ok){const e=Error(data.error||'Não foi possível concluir.');e.status=r.status;e.code=data.code;e.recoveryUrl=data.recoveryUrl;throw e;}return data;}
async function flushCloud(){await cloud.queue;if(cloud.error)throw Error(cloud.error);}
function updateCloudBadge(){const el=document.querySelector('.prototype');if(!el)return;if(cloud.mode==='live'){el.textContent=cloud.error?'ALTERAÇÕES NÃO SALVAS':cloud.pending?'SALVANDO…':'DADOS NA NUVEM';el.title=cloud.error||'Dados protegidos da sua empresa';el.style.cursor=cloud.error?'pointer':'';el.onclick=cloud.error?syncProblem:null;el.tabIndex=cloud.error?0:-1;el.setAttribute('role',cloud.error?'button':'status');el.onkeydown=cloud.error?e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();syncProblem();}}:null;}else el.textContent=cloud.mode==='loading'?'CARREGANDO CONTA…':'DADOS DE DEMONSTRAÇÃO';}
function showGoogleLinkRecovery(e){cloud.mode='error';let recovery='https://orbita-agentes-pedro.chiccoin65.chatgpt.site/#google-link';try{const u=new URL(e.recoveryUrl);if(u.protocol==='https:'&&u.hostname==='orbita-agentes-pedro.chiccoin65.chatgpt.site')recovery=u.href;}catch{}document.querySelector('#app').innerHTML='<main class="boot-screen"><div class="avatar">'+icon('orbit')+'</div><h1>Vamos conectar sua empresa.</h1><p>O Google confirmou sua conta. Falta autorizar o acesso aos dados da empresa que você já usa no Órbita.</p><a class="btn primary" href="'+esc(recovery)+'" target="_top">Vincular minha empresa original</a><p>Entre com seu ChatGPT original e confirme a conta Google. Seus dados continuam salvos.</p><form method="post" action="/auth/logout"><button class="btn">Trocar conta Google</button></form></main>';}
async function bootCloud(){document.querySelector('#app').innerHTML='<main class="boot-screen" role="status"><div class="avatar">'+icon('orbit')+'</div><h1>Preparando sua órbita…</h1><p>Carregando os dados da sua conta. Isso pode levar alguns instantes na primeira abertura.</p></main>';try{const r=await api('/bootstrap');cloud.mode='live';cloud.version=r.version;cloud.workspaceId=r.workspaceId;cloud.user=r.user;cloud.integrations=r.integrations;cloud.features=r.features;cloud.billing=r.billing;state=r.state;initializeV2();setupAgent=state.agents[0].id;chatAgent=setupAgent;chatMessages={};render();if(location.hash==='#google-link'&&cloud.user?.authProvider==='chatgpt'){history.replaceState(null,'',location.pathname+location.search);googleAccountForm();}}catch(e){if(e.status===401&&location.hostname==='orbita-google-entry.onrender.com'){location.assign('/login?expired=1');return;}if(e.code==='GOOGLE_LINK_REQUIRED'){showGoogleLinkRecovery(e);return;}if(e.status!==401){cloud.mode='error';document.querySelector('#app').innerHTML='<main class="boot-screen"><div class="avatar">'+icon('orbit')+'</div><h1>Vamos reconectar sua órbita.</h1><p role="alert">'+esc(e.message)+'</p><button class="btn primary" id="retry-boot">Tentar novamente</button><p>Os dados já salvos continuam na sua conta.</p></main>';document.querySelector('#retry-boot').onclick=bootCloud;return;}cloud.mode='demo';render();modal('Acesse sua conta',`<p style="font-size:13px;line-height:1.9">${e.status===401?'Entre para usar seus dados na nuvem, configurar integrações e operar sua empresa.':esc(e.message)}<br><br>Você também pode explorar os exemplos locais, sem conectar contas reais.</p><div class="modalfoot"><button class="btn" data-close>Explorar demonstração</button><a class="btn primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Entrar com ChatGPT</a></div>`);}}
function syncProblem(){modal('Alterações não sincronizadas',`<p style="font-size:13px;line-height:1.9">${esc(cloud.error||'Confira sua conexão.')}<br><br>As alterações desta tela ainda não foram confirmadas pelo servidor. Recarregar traz a versão salva e descarta as alterações pendentes.</p><div class="modalfoot"><button class="btn" data-close>Continuar olhando</button><button class="btn primary" id="reload-cloud">Descartar rascunho local e recarregar</button></div>`);document.querySelector('#reload-cloud').onclick=async()=>{document.querySelector('#modal').close();await reloadCloud(true);};}
async function reloadCloud(discard=false){try{if(cloud.sending||cloud.menuBusy||cloud.replySending)throw Error('Aguarde a operação em andamento antes de atualizar.');if(!discard&&cloud.menuDirty)throw Error('Salve o rascunho do cardápio antes de atualizar.');await cloud.queue;if(!discard)await flushCloud();const r=await api('/bootstrap');state=r.state;cloud.version=r.version;cloud.integrations=r.integrations;cloud.features=r.features;cloud.billing=r.billing;cloud.user=r.user;cloud.error=null;cloud.pending=0;cloud.queue=Promise.resolve();initializeV2();render();toast('Dados atualizados do servidor.');}catch(e){toast(e.message)}}
function render(){renderBase();updateCloudBadge();if(cloud.mode==='live'){const workspace=document.querySelector('.workspace strong');if(workspace)workspace.textContent=state.companyName;const ws=document.querySelector('.workspace small');if(ws)ws.textContent='Empresa na nuvem';const owner=document.querySelector('.owner strong');if(owner)owner.textContent=cloud.user?.name||'Você';const ownerSub=document.querySelector('.owner small');if(ownerSub)ownerSub.textContent='Proprietário · conta protegida';const mini=document.querySelector('.planmini strong');if(mini)mini.textContent=cloud.billing?.request?.status==='ACTIVE'?(cloud.billing.plans.find(p=>p.id===cloud.billing.request.plan_id)?.name||'Meu plano'):'Piloto da plataforma';const foot=document.querySelector('.planmini small');if(foot)foot.textContent=`${state.agents.length} de 4 números · piloto`;if(page==='agents'){document.querySelectorAll('.agentcard').forEach((card,i)=>{const a=state.agents[i];if(!a)return;const session=cloud.integrations.sessions?.find(s=>s.agent_id===a.id);const b=card.querySelector('.badge');if(b)b.textContent=a.paused?'Agente pausado':session?.status==='WORKING'?'WhatsApp conectado':'WhatsApp não conectado';const wrapper=document.createElement('div');wrapper.className='connection-controls';wrapper.innerHTML=`<small>${esc(sessionLabel(session?.status))}</small><div class="row"><button class="btn" data-connect="${esc(a.id)}">${icon('link')}Conectar</button><button class="textbtn" data-session-status="${esc(a.id)}">Verificar status</button></div>`;card.append(wrapper);});document.querySelectorAll('[data-connect]').forEach(b=>b.onclick=()=>connectionForm(b.dataset.connect));document.querySelectorAll('[data-session-status]').forEach(b=>b.onclick=()=>refreshSession(b.dataset.sessionStatus));const n=document.querySelector('.note .notetext');if(n)n.textContent='Personalize cada agente, conecte um servidor WhatsApp nos Ajustes e depois pareie cada número. O status só muda quando o servidor confirmar.';}const badFoot=[...document.querySelectorAll('.footnote')].find(e=>e.textContent.includes('Edições ficam neste navegador'));if(badFoot)badFoot.textContent='Dados da empresa salvos na nuvem. Integrações dependem das credenciais e da verificação de conexão.';}}
function configurationSteps(id=setupAgent){const list=demoConfigurationSteps(id);if(cloud.mode!=='live')return list;const session=cloud.integrations.sessions?.find(s=>s.agent_id===id);const wa=list.find(s=>s.id==='whatsapp');wa.done=session?.status==='WORKING';wa.blocked=!wa.done;wa.desc=wa.done?'Número pareado e verificado.':'Pareie o número e verifique a conexão.';const pay=list.find(s=>s.id==='payment');pay.done=state.paymentMode==='onsite'||!!cloud.integrations.asaas?.verifiedAt;pay.blocked=!pay.done;pay.desc=state.paymentMode==='onsite'?'Recebimento presencial definido.':cloud.integrations.asaas?.verifiedAt?'Asaas verificado · '+cloud.integrations.asaas.environment:'Conecte a chave Asaas nos Ajustes.';return list;}
function money(){if(cloud.mode!=='live')return moneyDemo();const income=state.entries.filter(e=>e.type==='income').reduce((n,e)=>n+e.amount,0),expense=state.entries.filter(e=>e.type==='expense').reduce((n,e)=>n+e.amount,0),payments=(cloud.integrations.payments||[]).filter(p=>p.environment==='production'),received=income+(cloud.integrations.paymentTotals?Number(cloud.integrations.paymentTotals.received)/100:payments.filter(p=>['RECEIVED','RECEIVED_IN_CASH'].includes(p.status)).reduce((n,p)=>n+p.value/100,0)),pending=cloud.integrations.paymentTotals?Number(cloud.integrations.paymentTotals.pending)/100:payments.filter(p=>['PENDING','CONFIRMED','OVERDUE'].includes(p.status)).reduce((n,p)=>n+p.value/100,0);return {received,expense,pending,net:received-expense};}
function home(){if(cloud.mode!=='live')return homeV2();const m=money(),sessions=cloud.integrations.sessions||[],connected=sessions.filter(s=>s.status==='WORKING').length;return head('Seu negócio em sintonia.','Atendimento, agenda e recebimentos da sua empresa.',button('Novo agendamento','booking',true,'plus'))+setupSummary()+`<div class="metrics">${metric('Recebido',cash(m.received),'Asaas produção + entradas registradas')}${metric('A receber',cash(m.pending),'Cobranças de produção em aberto')}${metric('Resultado estimado',cash(m.net),'Recebido menos despesas registradas')}${metric('WhatsApps conectados',connected+' / '+state.agents.length,'Sessões verificadas no conector','phone')}</div><div class="grid2"><section class="card"><div class="cardhead"><div><h2>Sua agenda</h2><p>Reservas registradas na nuvem</p></div><button class="textbtn" data-page="agenda">Abrir agenda ${icon('arrow')}</button></div>${bookingTable(state.bookings.filter(b=>['Confirmado','Aguardando pagamento'].includes(b.status)))}</section><section class="card"><div class="cardhead"><h2>Saúde do atendimento</h2><button class="textbtn" data-action="cloud-refresh">Atualizar</button></div><div class="settinglist"><div class="settingrow"><span>Servidor WhatsApp</span>${badge(cloud.integrations.waha?.verifiedAt?'Verificado':'Não conectado',cloud.integrations.waha?.verifiedAt?'green':'amber')}</div><div class="settingrow"><span>IA Gemini</span>${badge(cloud.integrations.gemini?.verifiedAt?'Verificada':'Não conectada',cloud.integrations.gemini?.verifiedAt?'green':'amber')}</div><div class="settingrow"><span>Asaas</span>${badge(cloud.integrations.asaas?.verifiedAt?cloud.integrations.asaas.environment:'Não conectado',cloud.integrations.asaas?.verifiedAt?'green':'amber')}</div><div class="settingrow"><span>Atualização automática</span>${badge(cloud.integrations.lastAutomaticSync&&Date.now()-Date.parse(cloud.integrations.lastAutomaticSync)<180000?'Ativa':'Não configurada','amber')}</div><div class="settingrow"><span>Respostas no mês</span><strong>${cloud.integrations.usage?.used||0} / ${(cloud.integrations.usage?.limit||1000).toLocaleString('pt-BR')}</strong></div><button class="textbtn" data-page="settings">Configurar integrações ${icon('arrow')}</button></div></section></div><p class="footnote">Piloto com dados reais da sua empresa. Pagamentos sandbox são testes e não entram no faturamento de produção. Assinatura comercial ainda não foi ativada.</p>`;}
function settings(){if(cloud.mode!=='live')return settingsDemo();return head('Conexões da sua empresa.','Credenciais protegidas no servidor. Nenhuma chave aparece nos dados do app.',button('Atualizar status','cloud-refresh',false,'arrow'))+`${googleAccountPanel()}${appearancePanel()}<div class="integrations">${[['waha','WhatsApp · WAHA','phone','Configure a URL HTTPS e a chave do seu servidor WAHA. Depois pareie cada número na aba Agentes.'],['asaas','Asaas','wallet','Cadastre sua chave no ambiente correto. Sandbox cria testes; produção cria cobranças reais.'],['gemini','Inteligência artificial','spark',cloud.integrations.gemini?.source==='platform'?'Gemini da plataforma ativo. Você pode usar sua própria chave se preferir.':'Conecte sua chave Gemini. O modelo ajuda na conversa; a agenda usa as regras do servidor.']].map(([id,title,ic,desc])=>`<section class="card integration"><div class="row between"><div class="row">${icon(ic)}<h2>${title}</h2></div>${badge(cloud.integrations[id]?.verifiedAt?'Verificado':'Não conectado',cloud.integrations[id]?.verifiedAt?'green':'amber')}</div><p>${desc}</p><button class="btn" data-provider="${id}">${cloud.integrations[id]?.configured?'Atualizar credencial':'Configurar conexão'}</button></section>`).join('')}<section class="card integration"><div class="row">${icon('users')}<h2>Empresa e equipe</h2></div><p>Defina o nome do negócio e os profissionais que aparecem na agenda e no atendimento.</p><button class="btn" data-action="business">Editar empresa</button></section></div><section class="card section-gap"><div class="cardhead"><h2>Preferências de operação</h2></div><div class="settinglist"><div class="settingrow"><div>Opções no WhatsApp<small>Listas são experimentais; enquetes e texto têm alternativa de atendimento.</small></div><select id="interaction-mode" style="max-width:210px">${[['poll','Enquetes clicáveis'],['list','Lista · experimental'],['text','Opções numeradas']].map(([v,t])=>`<option value="${v}" ${state.interactionMode===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="settingrow"><div>Recebimentos<small>${state.paymentMode==='online'?'Cobrança online pelo Asaas':'Pagamento presencial'}</small></div><button class="btn" data-action="payment-preference">Configurar</button></div><div class="settingrow"><div>Expediente<small>Dias, horários e intervalo compartilhados</small></div><button class="btn" data-action="hours">Editar</button></div></div></section><section class="card section-gap"><div class="cardhead"><div><h2>Seus dados</h2><p>Baixe os cadastros, reservas, lançamentos e histórico de atendimento da empresa.</p></div><button class="btn" data-action="export-data">Exportar dados</button></div><p class="footnote">Arquivo JSON para consulta. Fotos e vídeos devem ser baixados separadamente. Chaves de API não são incluídas. Restauração automática ainda não está disponível.</p></section><p class="footnote">Acesso protegido pela sua conta. Convites de equipe ainda não estão disponíveis. Webhooks WAHA usam autenticação de serviço; Asaas pode ser atualizado por consulta enquanto o recebimento externo de webhooks não é configurado.</p>`;}
function providerForm(provider){if(cloud.mode!=='live')return toast('Entre na sua conta para configurar credenciais.');const c=cloud.integrations[provider]||{},title={asaas:'Conectar Asaas',waha:'Conectar servidor WAHA',gemini:'Conectar IA Gemini'}[provider];modal(title,`<form autocomplete="off">${provider==='asaas'?`<div class="field"><label for="penv">Ambiente</label><select id="penv" name="environment"><option value="sandbox" ${c.environment!=='production'?'selected':''}>Sandbox · somente testes</option><option value="production" ${c.environment==='production'?'selected':''}>Produção · cobranças reais</option></select></div>`:''}${provider==='waha'?`<div class="field"><label for="purl">URL HTTPS do seu servidor WAHA</label><input id="purl" name="baseUrl" type="url" required value="${esc(c.baseUrl||'')}" placeholder="https://seu-servidor.exemplo.com"></div>`:''}<div class="field"><label for="pkey">Chave de API</label><input id="pkey" name="apiKey" type="password" required autocomplete="new-password" spellcheck="false" placeholder="Cole a chave aqui, sem enviar pelo chat"></div>${provider==='gemini'?`<div class="field"><label for="pmodel">Modelo (opcional)</label><input id="pmodel" name="model" value="${esc(c.model||'')}" placeholder="Automático entre os modelos disponíveis"></div>`:''}<small>A chave é enviada por conexão protegida, verificada com o provedor e armazenada criptografada. Ela não será exibida novamente. ${provider==='asaas'?'A verificação não cria uma cobrança.':''}</small><div class="formerror" role="alert"></div><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Verificar e salvar</button></div></form>`,async(f,form)=>{const submit=form.querySelector('button[type=submit]')||form.querySelector('.primary');submit.disabled=true;try{await flushCloud();const result=await api('/integrations',{method:'POST',body:{provider,...Object.fromEntries(f)}});form.querySelector('[name=apiKey]').value='';cloud.integrations=result.integrations;document.querySelector('#modal').close();render();toast(result.message);}catch(e){error(form,e.message)}finally{submit.disabled=false}});}
function businessForm(){modal('Empresa e profissionais',`<form><div class="field"><label for="company-name">Nome do negócio</label><input id="company-name" name="name" value="${esc(state.companyName||'')}" maxlength="80" required></div><div class="field"><label for="professionals">Profissionais (um nome por linha)</label><textarea id="professionals" name="professionals" required>${esc((state.professionals||['João','Lucas']).join('\n'))}</textarea></div><small>Profissionais com reservas não podem ser removidos por aqui. A agenda de cada nome é compartilhada entre os números.</small><div class="field" style="margin-top:16px"><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" name="reminders" style="width:auto" ${state.remindersEnabled?'checked':''}>Lembretes pelo WhatsApp (24h e 1h antes)</label><small>Precisam do serviço automático ativo; não dependem de manter esta tela aberta.</small></div><div class="formerror" role="alert"></div><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Salvar empresa</button></div></form>`,(f,form)=>{const names=[...new Set(f.get('professionals').split('\n').map(v=>v.trim()).filter(Boolean))];if(!f.get('name').trim()||!names.length||names.length>30)return error(form,'Informe o negócio e de 1 a 30 profissionais.');const removed=(state.professionals||[]).filter(n=>!names.includes(n));if(state.bookings.some(b=>removed.includes(b.professional)))return error(form,'Há reservas para um dos profissionais removidos. Mantenha o nome nesta etapa.');state.remindersEnabled=f.get('reminders')==='on';state.companyName=f.get('name').trim();state.professionals=names;state.agents.forEach(a=>{if(a.professional!=='Todos'&&!names.includes(a.professional))a.professional='Todos';});persist();document.querySelector('#modal').close();render();toast('Empresa enviada para salvar.');});}
function sessionLabel(status){return {WORKING:'WhatsApp conectado',STOPPED:'Desconectado · conectar WhatsApp',STARTING:'Preparando conexão',SCAN_QR_CODE:'Aguardando pareamento',FAILED:'Conexão interrompida · conectar novamente',UNAVAILABLE:'Servidor indisponível · tentar novamente',VERIFY_NUMBER:'Verificando número',NUMBER_MISMATCH:'Confira o número cadastrado'}[status]||'Ainda não conectado';}
async function refreshSession(id){try{await flushCloud();const r=await api('/sessions/'+encodeURIComponent(id)+'/status',{method:'POST',body:{}});cloud.integrations=await api('/integrations');render();toast(sessionLabel(r.status));}catch(e){toast(e.message)}}
function connectionForm(id){
 const a=state.agents.find(x=>x.id===id);let busy=false,cancelled=false;const controller=new AbortController();
 modal('Conectar '+esc(a.name),`<p class="connection-intro">WhatsApp cadastrado <strong>${esc(a.phone||'Não informado')}</strong></p><ol class="connection-steps"><li>Gere um QR ou código abaixo.</li><li>No WhatsApp, abra <strong>Aparelhos conectados</strong> e faça o pareamento.</li><li>Volte aqui e verifique a conexão.</li></ol><div class="connection-code" id="pair-result">Escolha como conectar seu WhatsApp.</div><div id="connection-progress" class="connection-progress" role="status" aria-live="polite" hidden></div><div class="formerror" role="alert" id="connection-error"></div><div class="connection-actions"><button class="btn primary" id="qr-session">Conectar com QR</button><button class="btn" id="pair-session">Conectar com código</button><button class="btn" id="verify-session">Verificar conexão</button><button class="textbtn" id="start-session">Preparar conexão novamente</button></div><p class="connection-hint">O código é de pareamento, não é um SMS. Na primeira conexão, o servidor gratuito pode demorar alguns minutos. Você pode fechar esta janela durante a espera.</p><button class="textbtn" id="test-own-number">Testar no meu número</button>`);
 const root=document.querySelector('#modal'),progress=root.querySelector('#connection-progress'),result=root.querySelector('#pair-result'),error=root.querySelector('#connection-error');
 const endpoint='/sessions/'+encodeURIComponent(id);root.addEventListener('close',()=>{cancelled=true;controller.abort();},{once:true});const request=(path,options={})=>api(path,{...options,signal:AbortSignal.any([controller.signal,AbortSignal.timeout(15000)])});
 const run=async(label,fn)=>{if(busy)return;busy=true;const buttons=[...root.querySelectorAll('.connection-actions button,#test-own-number')],old=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);root.setAttribute('aria-busy','true');progress.hidden=false;progress.textContent=label;error.textContent='';try{await flushCloud();const started=Date.now(),end=started+180000;let ready=false;while(!cancelled&&Date.now()<end){const r=await request(endpoint+'/ready',{method:'POST',body:{}});if(r.ready){ready=true;break;}progress.textContent='Acordando o servidor do WhatsApp · '+Math.floor((Date.now()-started)/1000)+'s. Você pode fechar esta janela e voltar depois.';await new Promise(resolve=>setTimeout(resolve,1500));}if(cancelled)return;if(!ready)throw Error('O servidor ainda está iniciando. Aguarde um pouco e tente novamente. Nenhuma mensagem foi enviada.');progress.textContent=label;await fn();}catch(e){if(!cancelled)error.textContent=e.message;}finally{busy=false;root.removeAttribute('aria-busy');progress.hidden=true;buttons.forEach((b,i)=>b.disabled=old[i]);if(cancelled)return;try{cloud.integrations=await api('/integrations');}catch{}root.querySelector('#test-own-number').disabled=cloud.integrations.sessions?.find(s=>s.agent_id===id)?.status!=='WORKING';}};
 const start=()=>request(endpoint+'/start',{method:'POST',body:{}});
 const pairingReady=async()=>{let s=await start();for(let attempt=0;!cancelled&&attempt<45;attempt++){if(['WORKING','SCAN_QR_CODE'].includes(s.status))return s;if(['FAILED','NUMBER_MISMATCH','VERIFY_NUMBER'].includes(s.status))throw Error('Não foi possível preparar o pareamento. Toque novamente em Conectar para renovar a tentativa.');progress.textContent='Preparando o pareamento com o WhatsApp…';await new Promise(resolve=>setTimeout(resolve,1000));s=await request(endpoint+'/status',{method:'POST',body:{}});}throw Error('O WhatsApp ainda não liberou o pareamento. Tente novamente em instantes.');};
 root.querySelector('#start-session').onclick=()=>run('Preparando conexão…',async()=>{await start();result.textContent='Conexão preparada. Escolha QR ou código.';});
 root.querySelector('#pair-session').onclick=()=>run('Solicitando código de pareamento…',async()=>{const s=await pairingReady();if(s.status==='WORKING'){result.textContent='WhatsApp conectado e verificado.';return;}const r=await request(endpoint+'/pair',{method:'POST',body:{}});if(r.pending)throw Error('O pareamento ainda está iniciando. Tente novamente em instantes.');if(typeof r.code!=='string'||!r.code.trim())throw Error('O WhatsApp não retornou um código. Tente conectar com QR.');result.textContent='';const code=document.createElement('strong');code.className='pairing-digits';code.textContent=r.code;result.append(code);const hint=document.createElement('p');hint.textContent='No WhatsApp: Aparelhos conectados → Conectar um aparelho → Conectar com número de telefone.';result.append(hint);});
 root.querySelector('#qr-session').onclick=()=>run('Gerando seu QR de conexão…',async()=>{const s=await pairingReady();if(s.status==='WORKING'){result.textContent='WhatsApp conectado e verificado.';return;}const r=await request(endpoint+'/qr',{method:'POST',body:{}});if(r.pending)throw Error('O pareamento está iniciando. Tente novamente em instantes.');if(r.mimetype!=='image/png'||typeof r.data!=='string'||! /^[A-Za-z0-9+/=]+$/.test(r.data))throw Error('O servidor não retornou uma imagem QR válida.');result.textContent='';const image=document.createElement('img');image.src='data:image/png;base64,'+r.data;image.alt='QR de pareamento do WhatsApp';image.style.cssText='width:100%;max-width:260px;display:block;margin:auto;background:white;padding:12px;box-sizing:border-box;border-radius:12px';result.append(image);});
 root.querySelector('#verify-session').onclick=()=>run('Verificando seu WhatsApp…',async()=>{const r=await request(endpoint+'/status',{method:'POST',body:{}});const labels={WORKING:'WhatsApp conectado e número verificado.',SCAN_QR_CODE:'Aguardando pareamento. Gere o QR e leia no WhatsApp.',STOPPED:'Conexão parada. Toque em Conectar com QR.',STARTING:'Conexão iniciando. Aguarde e verifique novamente.',FAILED:'A conexão precisa ser refeita. Toque em Conectar com QR.'};result.textContent=labels[r.status]||'Ainda não conectado. Gere um QR para parear.';updateCloudBadge();});
 root.querySelector('#test-own-number').disabled=cloud.integrations.sessions?.find(s=>s.agent_id===id)?.status!=='WORKING';root.querySelector('#test-own-number').onclick=()=>{root.close();testConnectionForm(id);};
}
function testConnectionForm(id){modal('Testar no próprio WhatsApp',`<form><div class="field"><label for="test-kind">Tipo de opções</label><select id="test-kind" name="mode"><option value="poll">Enquete clicável</option><option value="list">Lista · experimental</option><option value="buttons">Botões nativos · experimental</option><option value="text">Opções numeradas</option></select></div><p class="muted" style="font-size:12px;line-height:1.8">Envia uma mensagem de teste para o próprio número conectado. Só a visualização no aparelho confirma se os botões apareceram.</p><div class="formerror" role="alert"></div><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Enviar teste ao meu número</button></div></form>`,async(f,form)=>{try{const r=await api('/sessions/'+encodeURIComponent(id)+'/test',{method:'POST',body:{mode:f.get('mode')}});document.querySelector('#modal').close();toast(r.message);}catch(e){error(form,e.message)}});}
function finance(){if(cloud.mode!=='live')return financeDemo();const m=money(),payments=cloud.integrations.payments||[];return head('Recebimentos da empresa.','Serviço concluído e pagamento recebido são acompanhados separadamente.',button('Nova cobrança','new-charge',true,'plus'))+`<div class="metrics">${metric('Recebido',cash(m.received),'Produção + entradas registradas')}${metric('A receber',cash(m.pending),'Cobranças de produção')}${metric('Despesas',cash(m.expense),'Lançamentos registrados')}${metric('Resultado estimado',cash(m.net),'Recebido menos despesas registradas')}</div><section class="card"><div class="cardhead"><div><h2>Cobranças Asaas</h2><p>Até 100 cobranças recentes. Os totais consideram todo o histórico de produção.</p></div><button class="textbtn" data-action="refresh-payments">Consultar pagamentos</button></div>${payments.length?`<div class="tablewrap"><table class="table"><thead><tr><th>RESERVA</th><th>VALOR</th><th>AMBIENTE</th><th>STATUS</th><th>FATURA</th></tr></thead><tbody>${payments.map(p=>`<tr><td>${esc(state.bookings.find(b=>b.id===p.booking_id)?.client||p.booking_id)}</td><td>${cash(p.value/100)}</td><td>${p.environment==='production'?'Produção':'Sandbox · teste'}</td><td>${esc(p.status)}</td><td>${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Abrir fatura</a>`:'Consulta pendente'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma cobrança criada. Configure o Asaas em Ajustes para começar.</div>'}</section><section class="card section-gap"><div class="cardhead"><h2>Lançamentos manuais</h2><button class="textbtn" data-action="entry">Adicionar lançamento</button></div>${state.entries.length?`<div class="tablewrap"><table class="table"><thead><tr><th>DESCRIÇÃO</th><th>TIPO</th><th>VALOR</th></tr></thead><tbody>${state.entries.map(e=>`<tr><td>${esc(e.label)}</td><td>${e.type==='income'?'Entrada registrada':'Despesa'}</td><td>${cash(e.amount)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Sem lançamentos manuais.</div>'}</section><p class="footnote">Sandbox não é receita real. Status RECEIVED representa recebimento disponível; CONFIRMED fica separado. Consulte os pagamentos para atualizar enquanto o webhook externo Asaas não estiver configurado.</p>`;}
function chargeForm(){const list=state.bookings.filter(b=>b.status!=='Cancelado'&&b.price>0);if(!list.length)return toast('Cadastre uma reserva com valor antes de cobrar.');modal('Criar cobrança Asaas',`<form autocomplete="off"><div class="field"><label for="charge-booking">Reserva</label><select id="charge-booking" name="bookingId">${list.map(b=>`<option value="${esc(b.id)}">${esc(b.client)} · ${esc(b.service)} · ${cash(b.price)}</option>`).join('')}</select></div><div class="field"><label for="charge-document">CPF ou CNPJ do pagador</label><input id="charge-document" name="cpfCnpj" inputmode="numeric" type="password" autocomplete="off" required></div><div class="field"><label for="charge-type">Forma de pagamento</label><select id="charge-type" name="billingType"><option value="UNDEFINED">Cliente escolhe na fatura</option><option value="PIX">Pix</option></select></div><small>Ambiente selecionado: ${esc(cloud.integrations.asaas?.environment||'não configurado')}. A cobrança usará o preço da reserva salvo no servidor.</small><div class="formerror" role="alert"></div><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Criar cobrança</button></div></form>`,async(f,form)=>{const b=form.querySelector('.primary');b.disabled=true;try{await flushCloud();await api('/payments',{method:'POST',body:Object.fromEntries(f)});form.querySelector('[name=cpfCnpj]').value='';cloud.integrations=await api('/integrations');document.querySelector('#modal').close();render();toast('Cobrança registrada. Abra a fatura no financeiro.');}catch(e){error(form,e.message)}finally{b.disabled=false}});}
async function navigateTo(next,{chatTab='inbox',agentId=chatAgent}={}){
 const revision=(cloud.navigationRevision||0)+1;cloud.navigationRevision=revision;
 page=next;cloud.navigationError=null;
 const needsChat=cloud.mode==='live'&&next==='chats',needsMenu=cloud.mode==='live'&&next==='menu';
 if(next==='chats'){cloud.chatTab=chatTab;chatAgent=agentId;}
 cloud.navigationLoading=needsChat||needsMenu;render();window.scrollTo(0,0);
 if(!needsChat&&!needsMenu)return;
 const isCurrent=()=>cloud.navigationRevision===revision;
 try{
  if(needsMenu)await loadMenu(isCurrent);else if(chatTab==='inbox')await loadInbox(isCurrent);else await loadPreview(agentId,isCurrent);
 }catch(e){if(isCurrent())cloud.navigationError=e.message;}
 finally{if(isCurrent()){cloud.navigationLoading=false;render();}}
}
async function loadPreview(id,isCurrent=()=>true){if(cloud.previewPending?.agentId===id)return;await flushCloud();if(!isCurrent())return;const r=await api('/chat?agentId='+encodeURIComponent(id));if(!isCurrent()||cloud.previewPending?.agentId===id)return;chatMessages[id]=r.history;cloud.choices[id]=r.options||[];}
async function loadInbox(isCurrent=()=>true){const revision=(cloud.inboxRevision||0)+1;cloud.inboxRevision=revision;const r=await api('/conversations');if(!isCurrent()||cloud.inboxRevision!==revision)return;cloud.inbox=r.conversations;if(cloud.selectedConversation&&!r.conversations.some(c=>c.id===cloud.selectedConversation))cloud.selectedConversation=null;}
function previewChat(){
 const a=state.agents.find(x=>x.id===chatAgent)||state.agents[0],messages=chatMessages[a.id]||[],pending=cloud.previewPending?.agentId===a.id?cloud.previewPending:null,failed=cloud.previewError?.agentId===a.id?cloud.previewError:null;
 const renderMedia=m=>m.type?.startsWith('video/')?`<video controls preload="metadata" src="${esc(m.url)}" aria-label="${esc(m.name||'Vídeo de apoio')}" style="max-width:100%;max-height:240px"></video>`:`<img src="${esc(m.url)}" alt="${esc(m.name||'Imagem de apoio')}" style="max-width:100%;max-height:240px;border-radius:8px">`;
 return head('Teste seu agente','Converse como um cliente, com os serviços e horários cadastrados.')+`<section class="card chatlayout"><aside class="chatlist">${state.agents.map(v=>`<button class="chatperson ${v.id===a.id?'active':''}" data-chat-agent="${esc(v.id)}"><div class="avatar">${esc(v.name.charAt(0))}</div><div><strong>${esc(v.name)}</strong><small>${esc(v.label)}</small></div></button>`).join('')}</aside><div class="chatmain"><div class="chathead"><div><strong>${esc(a.name)}</strong><small>${a.paused?'Agente pausado':esc(a.personality)}</small></div><button class="btn" data-action="clear-chat" ${cloud.sending?'disabled':''}>Recomeçar fluxo</button></div><div class="bubbles" aria-live="polite" aria-busy="${!!pending}">${messages.length?messages.map(m=>`<div class="bubble ${m.who==='client'?'own':''}"><small>${m.who==='client'?'Você, como cliente':m.who==='human'?'Equipe':esc(a.name)}</small>${esc(m.text)}${m.document?'<a class="textbtn" href="/api/menus/pdf" target="_blank" rel="noopener noreferrer">📄 '+esc(m.document.name)+' ↗</a>':''}${(m.media||[]).map(renderMedia).join('')}</div>`).join(''):`<div class="bubble"><small>${esc(a.name)}</small>Oi! Sou ${esc(a.name)}, assistente virtual de ${esc(state.companyName)}. Escolha uma opção ou escreva para começar.</div>`}${pending?`${pending.message?`<div class="bubble own"><small>Você, como cliente</small>${esc(pending.message)}</div>`:''}<div class="bubble"><span role="status">Preparando resposta…</span></div>`:''}</div>${failed?`<div class="preview-error" role="alert">${esc(failed.error)} <button class="textbtn" id="retry-preview">Tentar novamente</button></div>`:''}<div class="quickchoices">${(cloud.choices[a.id]||[]).map(o=>`<button data-real-choice="${esc(o.id)}" ${cloud.sending||a.paused?'disabled':''}>${esc(o.label)}</button>`).join('')}</div><form class="chatinput" id="chat-form"><input name="message" maxlength="2000" required value="${esc(failed?.message||'')}" placeholder="Escreva para ${esc(a.name)}…" aria-label="Mensagem de teste" ${cloud.sending||a.paused?'disabled':''}><button class="btn primary" aria-label="Enviar mensagem" ${cloud.sending||a.paused?'disabled':''}>${cloud.sending?'Aguarde…':icon('send')}</button></form></div></section><p class="footnote">Ambiente de teste: reservas e pagamentos são simulados. Nenhuma mensagem é enviada ao WhatsApp. Se a IA demorar, as opções guiadas continuam disponíveis.</p>`;
}
function chats(){if(cloud.mode!=='live')return chatsDemo();const top=`<div class="tabs" style="margin-bottom:20px"><button data-chat-tab="inbox" class="${cloud.chatTab==='inbox'?'active':''}">Atendimentos WhatsApp</button><button data-chat-tab="preview" class="${cloud.chatTab==='preview'?'active':''}">Testar meus agentes</button></div>`;if(cloud.navigationLoading)return top+'<section class="card" aria-busy="true"><div class="empty" role="status">Carregando conversas…</div></section>';if(cloud.navigationError)return top+`<section class="card"><div class="empty" role="alert">${esc(cloud.navigationError)}<br><button class="btn" id="retry-navigation">Tentar novamente</button></div></section>`;if(cloud.chatTab==='preview')return top+previewChat();const selected=cloud.inbox.find(c=>c.id===cloud.selectedConversation);return top+head('Atendimentos WhatsApp','Conversas reais recebidas pelos números conectados.',button('Atualizar conversas','inbox-refresh',false,'arrow'))+`<section class="card chatlayout"><aside class="chatlist">${cloud.inbox.map(c=>`<button class="chatperson ${c.id===selected?.id?'active':''}" data-inbox="${esc(c.id)}"><div class="avatar">${icon('chat')}</div><div><strong>${esc(c.contact.split('@')[0])}</strong><small>${esc(state.agents.find(a=>a.id===c.agent_id)?.name||'Agente')} · ${c.data.human?'Humano':'IA'}</small></div></button>`).join('')||'<div class="empty">Nenhum atendimento recebido ainda.</div>'}</aside><div class="chatmain">${selected?`<div class="chathead"><div><strong>${esc(selected.contact.split('@')[0])}</strong><small>${selected.data.human?'Atendimento humano ativo':'Automação ativa'}</small></div><button class="btn" id="take-over">${selected.data.human?'Retomar IA':'Assumir atendimento'}</button></div><div class="bubbles">${(selected.data.history||[]).map(m=>`<div class="bubble ${m.who==='client'?'':'own'}"><small>${m.who==='client'?'Cliente':m.who==='human'?'Equipe':'Agente'}</small>${esc(m.text)}</div>`).join('')}</div>${selected.data.human?`<form id="human-reply" class="chatinput"><input name="message" required maxlength="3000" aria-label="Resposta humana" placeholder="Escreva sua resposta ao cliente…" value="${esc(cloud.replyDrafts?.[selected.id]||'')}" ${cloud.replySending===selected.id?'disabled':''}><button class="btn primary" ${cloud.replySending===selected.id?'disabled':''}>${cloud.replySending===selected.id?'Enviando…':'Enviar'}</button></form>`:'<div class="empty" style="padding:18px">Assuma o atendimento para responder como pessoa.</div>'}`:'<div class="empty">Selecione uma conversa para acompanhar o atendimento.</div>'}</div></section>`;}
async function say(t,choiceId,reset=false,requestId){
 if(cloud.mode!=='live')return sayDemo(t);if(cloud.sending)return toast('Aguarde a resposta atual.');
 const agentId=chatAgent,id=requestId||uid();let version; cloud.sending=true;cloud.previewError=null;cloud.previewPending={agentId,message:t,choiceId,reset,requestId:id};renderPreviewUpdate();
 try{
 await flushCloud();version=cloud.version;const result=await api('/chat',{method:'POST',body:{agentId,message:t,choiceId,reset,requestId:id},signal:AbortSignal.timeout(45000)});
 chatMessages[agentId]=result.history;cloud.choices[agentId]=result.options||[];
 if(result.state&&cloud.version===version&&!cloud.pending){state=result.state;cloud.version=result.version;}
 }catch(e){cloud.previewError={agentId,message:t,choiceId,reset,requestId:id,error:e.message};toast(e.message);}
 finally{cloud.sending=false;cloud.previewPending=null;renderPreviewUpdate();if(page==='chats'&&cloud.chatTab==='preview'&&chatAgent===agentId){const bubbles=document.querySelector('.bubbles');bubbles?.scrollTo(0,bubbles.scrollHeight);}}
}
function renderPreviewUpdate(){if(page!=='chats'||cloud.chatTab!=='preview')return;const current=document.querySelector('.chatmain');if(!current||typeof document.createElement!=='function'){render();return;}const template=document.createElement('template');template.innerHTML=previewChat();const next=template.content.querySelector('.chatmain');if(!next){render();return;}const view=typeof window!=='undefined'?window:null,x=view?.scrollX||0,y=view?.scrollY||0;for(const selector of ['.bubbles','.quickchoices']){const old=current.querySelector(selector),fresh=next.querySelector(selector);if(old&&fresh)old.innerHTML=fresh.innerHTML;}current.querySelector('.preview-error')?.remove();const failure=next.querySelector('.preview-error');if(failure)current.querySelector('.quickchoices')?.before(failure);const input=current.querySelector('#chat-form input'),send=current.querySelector('#chat-form button');if(input){input.readOnly=!!cloud.sending;input.disabled=!!state.agents.find(a=>a.id===chatAgent)?.paused;if(cloud.sending)input.value='';else if(cloud.previewError?.agentId===chatAgent)input.value=cloud.previewError.message||'';}if(send){send.disabled=!!cloud.sending||!!input?.disabled;send.innerHTML=cloud.sending?'Aguarde…':icon('send');}const reset=current.querySelector('[data-action="clear-chat"]');if(reset)reset.disabled=!!cloud.sending;current.querySelectorAll('[data-real-choice]').forEach(b=>b.onclick=()=>say('',b.dataset.realChoice));current.querySelector('#retry-preview')?.addEventListener('click',()=>{const e=cloud.previewError;if(e)say(e.message,e.choiceId,e.reset,e.requestId)});if(view&&view.scrollY!==y)view.scrollTo({left:x,top:y,behavior:'instant'});}
function album(id){if(cloud.mode!=='live')return albumDemo(id);const g=state.gallery.find(x=>x.id===id);modal(esc(g.title),`<p class="muted" style="font-size:12px;line-height:1.8;margin-bottom:18px">${esc(g.desc)}</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${g.media.map((m,i)=>`<div>${m.type?.startsWith('video/')?`<video controls preload="metadata" src="${esc(m.url)}" style="width:100%;height:140px;border-radius:8px"></video>`:`<img src="${esc(m.url)}" alt="${esc(g.title)} · arquivo ${i+1}" style="width:100%;height:140px;object-fit:cover;border-radius:8px">`}<small>${esc(m.name||'Arquivo '+(i+1))}</small></div>`).join('')}</div>${g.media.length?'':'<div class="empty">Este álbum ainda não tem arquivos.</div>'}<div class="field" style="margin-top:20px"><label for="cloud-upload">Adicionar imagem ou vídeo (até 10 MB)</label><input id="cloud-upload" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm"></div><small>Arquivos protegidos e salvos na sua conta. Até 20 arquivos por álbum no piloto.</small><div class="formerror" role="alert" id="upload-error"></div>`);document.querySelector('#cloud-upload').onchange=async e=>{const f=e.target.files[0];if(!f)return;const input=e.target;input.disabled=true;try{await flushCloud();const form=new FormData();form.append('file',f);form.append('albumId',id);const r=await api('/media',{method:'POST',body:form});g.media.push(r.media);persist();await flushCloud();document.querySelector('#modal').close();render();album(id);toast('Arquivo salvo na sua conta.');}catch(err){const errorEl=document.querySelector('#upload-error');if(errorEl)errorEl.textContent=err.message;}finally{input.disabled=false;}};}
function livePaymentForm(){modal('Preferência de recebimento',`<form><div class="field"><label for="live-payment">Como receber pelos serviços?</label><select id="live-payment" name="mode"><option value="onsite" ${state.paymentMode==='onsite'?'selected':''}>Pagamento presencial</option><option value="online" ${state.paymentMode==='online'?'selected':''}>Cobrança Asaas após reservar horário</option></select></div><small>No modo online, o agente reserva o horário por 15 minutos e pede CPF/CNPJ para criar a cobrança. Conecte Asaas antes de ativar esse modo. A consulta ao provedor é necessária para confirmar recebimento.</small><div class="formerror" role="alert"></div><div class="modalfoot"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Salvar preferência</button></div></form>`,(f,form)=>{if(f.get('mode')==='online'&&!cloud.integrations.asaas?.verifiedAt)return error(form,'Verifique a chave Asaas em Ajustes antes de ativar cobrança online.');state.paymentMode=f.get('mode');persist();document.querySelector('#modal').close();render();});}
function bind(){document.querySelectorAll('[data-plan-request]').forEach(b=>b.onclick=()=>requestPlanForm(b.dataset.planRequest));document.querySelector('#plan-requests')?.addEventListener('click',planRequests);bindV2();bindBusinessTheme();if(cloud.mode!=='live')return;document.querySelector('#retry-navigation')?.addEventListener('click',()=>navigateTo('chats',{chatTab:cloud.chatTab,agentId:chatAgent}));document.querySelector('#retry-preview')?.addEventListener('click',()=>{const failed=cloud.previewError;if(failed&&failed.agentId===chatAgent)say(failed.message,failed.choiceId,failed.reset,failed.requestId);});document.querySelectorAll('[data-provider]').forEach(b=>b.onclick=()=>providerForm(b.dataset.provider));document.querySelector('#interaction-mode')?.addEventListener('change',e=>{state.interactionMode=e.target.value;persist();toast('Preferência enviada para salvar.');});document.querySelectorAll('[data-setup-step]').forEach(b=>{if(b.dataset.setupStep==='whatsapp')b.onclick=()=>connectionForm(setupAgent);if(b.dataset.setupStep==='test')b.onclick=()=>navigateTo('chats',{chatTab:'preview',agentId:setupAgent});if(b.dataset.setupStep==='payment')b.onclick=()=>livePaymentForm();});document.querySelectorAll('[data-test-agent],[data-chat-agent]').forEach(b=>b.onclick=()=>navigateTo('chats',{chatTab:'preview',agentId:b.dataset.testAgent||b.dataset.chatAgent}));document.querySelectorAll('[data-page="chats"]').forEach(b=>b.onclick=()=>navigateTo('chats'));document.querySelectorAll('[data-chat-tab]').forEach(b=>b.onclick=()=>navigateTo('chats',{chatTab:b.dataset.chatTab,agentId:chatAgent}));if(page==='chats'&&cloud.chatTab==='preview'){const choices=document.querySelector('.quickchoices');if(choices){choices.querySelectorAll('[data-real-choice]').forEach(b=>b.onclick=()=>say(b.textContent,b.dataset.realChoice));}}document.querySelectorAll('[data-inbox]').forEach(b=>b.onclick=()=>{cloud.selectedConversation=b.dataset.inbox;render();});document.querySelector('#take-over')?.addEventListener('click',async()=>{try{const c=cloud.inbox.find(v=>v.id===cloud.selectedConversation);await api('/conversations/'+encodeURIComponent(c.id),{method:'PUT',body:{human:!c.data.human}});await loadInbox();render();}catch(e){toast(e.message)}});document.querySelector('#human-reply input')?.addEventListener('input',e=>{(cloud.replyDrafts||={})[cloud.selectedConversation]=e.target.value;});document.querySelector('#human-reply')?.addEventListener('submit',async e=>{e.preventDefault();if(cloud.replySending)return;const id=cloud.selectedConversation,message=String(new FormData(e.target).get('message')||'').trim();if(!message)return; (cloud.replyDrafts||={})[id]=message;cloud.replySending=id;render();try{await api('/conversations/'+encodeURIComponent(id),{method:'POST',body:{message}});delete cloud.replyDrafts[id];await loadInbox();}catch(err){toast(err.message)}finally{cloud.replySending=null;render();}});}
async function exportData(){try{await flushCloud();toast('Preparando exportação…');const data=await api('/export'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='orbita-dados-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Exportação preparada para download.');}catch(e){toast(e.message);}}
function action(a){if(a==='appearance'){const next=appearance()==='light'?'dark':'light';state.theme=next;try{localStorage.setItem('orbita-appearance',next)}catch{}render();return;}if(a==='logout')return signOutCloud();if(cloud.mode==='live'){if(a==='help')return modal('Sobre a Órbita','<p>A Órbita reúne agentes de IA, conversas, agenda, catálogo e recebimentos da sua empresa.</p><p>Seus dados ficam na sua conta. Confira as conexões em Ajustes e experimente o agente no Laboratório antes de colocá-lo para atender.</p>');if(a==='google-account')return googleAccountForm();if(a==='export-data')return exportData();if(a==='cloud-refresh')return reloadCloud();if(a==='business')return businessForm();if(a==='hours')return hoursForm();if(a==='payment-preference')return livePaymentForm();if(a==='new-charge')return chargeForm();if(a==='refresh-payments')return(async()=>{try{await flushCloud();const r=await api('/payments/refresh',{method:'PUT',body:{}});await reloadCloud();toast(r.updated+' cobrança(s) consultada(s).');}catch(e){toast(e.message)}})();if(a==='inbox-refresh')return loadInbox().then(render).catch(e=>toast(e.message));if(a==='clear-chat')return say('menu',undefined,true);if(a==='reset')return toast('Dados reais não são substituídos pelos exemplos.');if(a==='integration-info')return providerForm('asaas');}return actionV2(a);}
function bindBusinessTheme(){document.querySelectorAll('[data-menu-action]').forEach(b=>b.onclick=()=>menuAction(b.dataset.menuAction));document.querySelectorAll('[data-menu-field]').forEach(el=>el.oninput=()=>{if(!cloud.menu)return;cloud.menu.draft[el.dataset.menuField]=el.value;cloud.menuDirty=true;document.querySelector('#menu-dirty')?.removeAttribute('hidden');});document.querySelectorAll('[data-menu-item]').forEach(el=>el.oninput=()=>{const item=cloud.menu?.draft.items.find(i=>i.id===el.dataset.menuItem);if(!item)return;const field=el.dataset.itemField;item[field]=field==='available'?el.checked:field==='price'?(el.value===''?null:Number(el.value)):el.value;cloud.menuDirty=true;document.querySelector('#menu-dirty')?.removeAttribute('hidden');});document.querySelectorAll('[data-menu-remove]').forEach(b=>b.onclick=()=>{cloud.menu.draft.items=cloud.menu.draft.items.filter(i=>i.id!==b.dataset.menuRemove);cloud.menuDirty=true;render();});document.querySelector('#menu-pdf-upload')?.addEventListener('change',e=>createMenuFromPdf(e.target.files[0]));}

async function loadMenu(isCurrent=()=>true,force=false){if(cloud.menuDirty&&!force)return;const data=await api('/menus');if(!isCurrent()||cloud.menuDirty&&!force)return;cloud.menu=data;cloud.menuDirty=false;cloud.menuError=null;}
function menuPage(){if(cloud.mode!=='live')return head('Seu PDF vira um cardápio virtual.','Envie o arquivo. A IA organiza as opções e cria uma página com link.')+note('Entre na sua conta para criar e guardar seu cardápio.');const m=cloud.menu;if(cloud.navigationLoading||!m)return head('Seu cardápio virtual','Do PDF para um link, em um só lugar.')+`<section class="card empty" role="status">${cloud.navigationError?esc(cloud.navigationError)+' <button class="btn" data-menu-action="reload">Tentar novamente</button>':'Carregando seu cardápio…'}</section>`;const d=m.draft,busy=!!cloud.menuBusy,disabled=busy?'disabled':'',ready=d.items.length>0,missing=d.items.filter(i=>i.available&&i.price===null),groups=[...new Set(d.items.map(i=>i.category))];
return head('Seu PDF. Seu cardápio. Seu link.','Envie o arquivo e deixe a IA organizar a página para você.')+`
${cloud.menuError?`<div class="note" role="alert"><div><strong>A criação foi pausada.</strong><p>${esc(cloud.menuError)}</p><small>Seu PDF continua salvo. O que já foi lido fica guardado para continuar.</small></div><button class="textbtn" data-menu-action="reload" ${disabled}>Atualizar</button></div>`:''}
${m.publicUrl?`<section class="card menu-link-card"><div><div class="hero-label">${m.publicationCurrent?'PRONTO PARA COMPARTILHAR':'PÁGINA PUBLICADA'}</div><h2>Seu cardápio está no ar.</h2><p>${m.publicationCurrent?'O atendimento já pode enviar este link.':'O link ainda mostra a última versão publicada. Alterações pendentes aparecem na prévia abaixo.'}</p></div><a class="menu-public-link" href="${esc(m.publicUrl)}" target="_blank" rel="noopener noreferrer">${esc(m.publicUrl)} ↗</a><div class="row"><button class="btn primary" data-menu-action="copy-link">Copiar link</button><a class="btn" href="${esc(m.publicUrl)}" target="_blank" rel="noopener noreferrer">Abrir cardápio ↗</a></div></section>`:''}
${m.publicationCurrent?'<details class="menu-edit-details"><summary>Trocar PDF ou gerar novamente</summary>':''}<section class="card menu-create"><div class="menu-create-icon">${icon('receipt')}</div><div class="hero-label">PDF → CARDÁPIO VIRTUAL</div><h2>${busy?'Montando seu cardápio…':m.hasPdf?esc(m.filename):'Comece pelo seu PDF'}</h2><p>${busy?esc(cloud.menuBusy):m.virtualEnabled?'A IA lê as páginas, organiza categorias e preços e publica seu cardápio com um link.':'Guarde seu PDF para o agente enviar aos clientes. A página virtual faz parte do recurso avançado.'}</p>${busy?'<div class="menu-working" role="status" aria-live="polite"><span></span>Cada parte pode levar alguns segundos. Você pode continuar usando o app.</div>':`<label class="btn primary" for="menu-pdf-upload">${icon('plus')}${m.virtualEnabled?(m.hasPdf?'Escolher outro PDF e criar link':'Escolher PDF e criar link'):(m.hasPdf?'Trocar PDF':'Escolher PDF')}</label><input class="menu-upload-input" id="menu-pdf-upload" type="file" accept="application/pdf,.pdf" aria-label="Enviar cardápio PDF" ${disabled}/>${m.hasPdf&&m.virtualEnabled?`<button class="btn" data-menu-action="create">${m.importProgress?.status==='processing'?'Continuar criação do cardápio':m.published?'Gerar novamente com o PDF salvo':'Criar link com o PDF salvo'}</button>`:''}`}
<small>${m.virtualEnabled?'O link ficará público e o agente poderá enviá-lo pelo WhatsApp. Preços ilegíveis aparecem como Consulte. A leitura é feita por partes e o progresso fica salvo.':'Somente o arquivo será salvo.'} PDF de até 5 MB.</small>${m.hasPdf?'<a class="textbtn" href="/api/menus/pdf" target="_blank" rel="noopener noreferrer">Ver PDF salvo ↗</a>':''}</section>${m.publicationCurrent?'</details>':''}
${missing.length?`<section class="note"><div><strong>${missing.length} preço(s) para conferir quando quiser.</strong><p>Estes valores não ficaram claros no PDF e aparecem como Consulte na página. Você pode corrigi-los em “Editar informações e itens”.</p><p>${missing.map(i=>esc(i.title)).join(' · ')}</p></div></section>`:''}
${ready?`<section class="card menu-generated-preview" data-menu-preview-theme="${esc(d.theme)}"><div class="menu-preview-heading"><div class="hero-label">PRÉVIA DO CARDÁPIO · ${d.items.length} OPÇÕES</div><h2>${esc(d.title)}</h2>${d.subtitle?`<p>${esc(d.subtitle)}</p>`:''}</div>${groups.map(category=>`<div class="menu-preview-category"><h3>${esc(category)}</h3>${d.items.filter(i=>i.category===category).map(i=>`<div class="menu-preview-item"><div><strong>${esc(i.title)}</strong>${i.desc?`<p>${esc(i.desc)}</p>`:''}${!i.available?'<small>Indisponível</small>':''}</div><span class="${i.price===null?'muted':''}">${i.price===null?'Consulte':cash(i.price)}</span></div>`).join('')}</div>`).join('')}</section>`:''}
<details class="menu-edit-details" ${missing.length?'open':''}><summary>Editar informações e itens ${ready?'('+d.items.length+')':''}</summary><section class="card menu-editor"><div class="cardhead"><div><div class="hero-label">AJUSTES OPCIONAIS</div><h2>Editar informações e itens</h2><p>Alterações no rascunho só chegam ao link depois de publicar novamente.</p></div><span id="menu-dirty" class="badge amber" ${cloud.menuDirty?'':'hidden'}>Alterações não salvas</span></div><fieldset ${disabled}><div class="menu-editor-fields"><div class="field"><label for="menu-title">Nome público do estabelecimento</label><input id="menu-title" data-menu-field="title" maxlength="100" value="${esc(d.title)}"></div><div class="field"><label for="menu-subtitle">Mensagem de apresentação (opcional)</label><input id="menu-subtitle" data-menu-field="subtitle" maxlength="200" value="${esc(d.subtitle)}"></div><div class="field"><label for="menu-whatsapp">WhatsApp público (opcional, com 55 + DDD)</label><input id="menu-whatsapp" data-menu-field="whatsapp" inputmode="tel" maxlength="24" value="${esc(d.whatsapp)}" placeholder="Ex.: 5543999999999"></div></div><p class="footnote">O telefone informado aqui ficará público no link. Sem telefone, a página apenas apresenta as opções. Não há pagamento nem confirmação de pedido nesta página.</p><div class="menu-items">${(missing.length?[...d.items].sort((a,b)=>(a.price===null?0:1)-(b.price===null?0:1)):d.items).slice(0,cloud.menuEditLimit||40).map((i,index)=>`<article class="menu-item-editor"><div class="row between"><strong>Item ${index+1}</strong><button class="textbtn" data-menu-remove="${esc(i.id)}">Remover</button></div><div class="menu-editor-fields"><div class="field"><label for="item-title-${index}">Nome</label><input id="item-title-${index}" data-menu-item="${esc(i.id)}" data-item-field="title" maxlength="100" value="${esc(i.title)}"></div><div class="field"><label for="item-category-${index}">Categoria</label><input id="item-category-${index}" data-menu-item="${esc(i.id)}" data-item-field="category" maxlength="70" value="${esc(i.category)}"></div><div class="field"><label for="item-description-${index}">Descrição</label><input id="item-description-${index}" data-menu-item="${esc(i.id)}" data-item-field="desc" maxlength="500" value="${esc(i.desc)}"></div><div class="field"><label for="item-price-${index}">Preço (R$) ${i.price===null?'· revisar':''}</label><input id="item-price-${index}" type="number" min="0" max="1000000" step="0.01" data-menu-item="${esc(i.id)}" data-item-field="price" value="${i.price===null?'':i.price}"></div></div><label class="menu-available"><input type="checkbox" data-menu-item="${esc(i.id)}" data-item-field="available" ${i.available?'checked':''}>Disponível na página</label></article>`).join('')||'<div class="empty">Os itens identificados no PDF aparecerão aqui.</div>'}</div><div class="row menu-editor-actions">${d.items.length>(cloud.menuEditLimit||40)?'<button class="btn" data-menu-action="more-items">Mostrar mais itens</button>':''}<button class="btn" data-menu-action="add" ${d.items.length>=2000?'disabled':''}>${icon('plus')} Adicionar item</button><button class="btn primary" data-menu-action="save">Salvar alterações</button></div></fieldset></section>
</details>
${ready?`<div class="menu-finish-actions">${!m.publicationCurrent||cloud.menuDirty?`<button class="btn primary" data-menu-action="publish" ${busy||!m.virtualEnabled?'disabled':''}>${m.published?'Salvar e atualizar link':'Publicar link'}</button>`:''}${m.published?`<button class="textbtn" data-menu-action="unpublish" ${disabled}>Retirar link do ar</button>`:''}</div>`:''}
${m.hasPdf?`<details class="menu-edit-details"><summary>O que o agente envia ao cliente?</summary><div class="card menu-publication"><div class="row menu-publish-actions"><button class="btn ${m.delivery==='pdf'?'primary':''}" data-menu-action="use-pdf" ${disabled}>PDF ${m.delivery==='pdf'?'✓':''}</button><button class="btn ${m.delivery==='virtual'?'primary':''}" data-menu-action="use-virtual" ${busy||!m.publicUrl?'disabled':''}>Link do cardápio ${m.delivery==='virtual'?'✓':''}</button></div></div></details>`:''}`;}
async function createMenuFromPdf(file){if(!file||cloud.menuBusy||!cloud.menu)return;if(cloud.menuDirty)return toast('Salve as alterações dos itens antes de trocar o PDF.');if(file.size>5*1024*1024)return toast('Escolha um PDF de até 5 MB.');const form=new FormData();form.append('file',file);form.append('version',String(cloud.menu.version));await createMenuFlow(form);}
async function createMenuFlow(form){if(cloud.menuBusy||!cloud.menu)return;cloud.menuError=null;cloud.menuBusy=form?'Enviando o PDF…':'Lendo as páginas e organizando as opções…';render();try{await flushCloud();if(form){cloud.menu=await api('/menus/pdf',{method:'POST',body:form,signal:AbortSignal.timeout(65000)});cloud.menuDirty=false;}if(cloud.menu.virtualEnabled){cloud.menuBusy='Lendo todas as páginas, identificando as opções e preparando seu link…';render();do{const progress=cloud.menu.importProgress;if(progress?.status==='processing'){cloud.menuBusy='Lendo página '+Math.min(progress.completedPages+1,progress.totalPages)+' de '+progress.totalPages+' · '+progress.itemCount+' opções já identificadas…';render();}cloud.menu=await api('/menus/create',{method:'POST',body:{version:cloud.menu.version,publish:true,...(progress?.status==='processing'?{jobId:progress.id}:{})},signal:AbortSignal.timeout(65000)});}while(cloud.menu.importProgress?.status==='processing');toast(cloud.menu.creationMessage||'Cardápio pronto.');}else toast('PDF salvo. Seu agente já pode enviar o arquivo.');}catch(e){cloud.menuError=e.message;try{const data=await api('/menus');cloud.menu=data;cloud.menuDirty=false;}catch{}}finally{cloud.menuBusy=null;render();}}

async function runMenuRequest(path,opts,label){if(cloud.menuBusy)return;cloud.menuBusy=label;cloud.menuError=null;render();try{const data=await api(path,{...opts,signal:AbortSignal.timeout(65000)});cloud.menu=data;cloud.menuDirty=false;return true;}catch(e){cloud.menuError=e.name==='TimeoutError'?'A operação demorou. Recarregue para consultar o resultado antes de repetir.':e.message;return false;}finally{cloud.menuBusy=null;render();}}
async function menuAction(action){if(cloud.menuBusy)return;const m=cloud.menu;if(action==='reload'){try{await loadMenu(()=>true,true);render();}catch(e){toast(e.message)}return;}if(!m)return;if(action==='more-items'){cloud.menuEditLimit=(cloud.menuEditLimit||40)+40;render();return;}if(action==='copy-link'){try{await navigator.clipboard.writeText(m.publicUrl);toast('Link copiado.');}catch{toast('Abra o cardápio e copie o endereço do navegador.');}return;}if(action==='create'){if(cloud.menuDirty)return toast('Salve as alterações antes de gerar novamente.');await createMenuFlow();return;}if(action==='add'){if(m.draft.items.length>=2000)return;m.draft.items.push({id:uid(),category:'Outras opções',title:'',desc:'',price:null,available:true});cloud.menuDirty=true;render();return;}if(action==='save'){await runMenuRequest('/menus',{method:'PUT',body:{version:m.version,draft:m.draft}},'Salvando rascunho…');return;}if(action==='extract'){modal('Transformar PDF em rascunho',`<p style="line-height:1.9">O arquivo será lido pela IA para identificar os itens. Isso substitui o rascunho salvo; a página publicada continua como estava. Depois, revise todos os preços e descrições antes de publicar.</p><div class="modalfoot"><button class="btn" data-close>Voltar</button><button class="btn primary" id="confirm-menu-extract">Ler PDF e gerar rascunho</button></div>`);document.querySelector('#confirm-menu-extract').onclick=async()=>{document.querySelector('#modal').close();if(cloud.menuDirty)return toast('Salve o rascunho antes de continuar.');await runMenuRequest('/menus/extract',{method:'POST',body:{version:m.version}},'Lendo PDF e preparando itens para revisão…');};return;}if(action==='publish'){if(cloud.menuDirty){const saved=await runMenuRequest('/menus',{method:'PUT',body:{version:m.version,draft:m.draft}},'Salvando os ajustes…');if(!saved)return;}await runMenuRequest('/menus/publish',{method:'POST',body:{version:cloud.menu.version,reviewed:true}},'Publicando seu cardápio…');return;}if(action==='unpublish'){await runMenuRequest('/menus/unpublish',{method:'POST',body:{version:m.version}},'Retirando página do ar…');return;}if(action==='use-pdf'||action==='use-virtual')await runMenuRequest('/menus/delivery',{method:'POST',body:{version:m.version,delivery:action==='use-pdf'?'pdf':'virtual'}},'Atualizando o atendimento…');}

bootCloud();

function googleAccountPanel(){const google=cloud.user?.authProvider==='google';return `<section class="card section-gap"><div class="cardhead"><div><h2>Acesso à sua conta</h2><p>${google?'Conectado com Google':'Conectado com ChatGPT'} · ${esc(cloud.user?.email||'')}</p></div>${google?button('Sair da conta','logout'):button('Configurar acesso Google','google-account')+button('Sair da conta','logout')}</div><p class="footnote">${google?'Sua sessão Google permite acessar esta empresa.':'Vincule uma conta Google à sua empresa atual antes do primeiro acesso pelo novo endereço.'}</p></section>`;}
async function googleAccountForm(){try{const status=await api('/google-account/status');modal('Acessar com Google',`<p style="line-height:1.8">${status.configured?'O acesso Google está configurado. Escolha a conta que terá acesso à sua empresa atual.':status.missing?.includes('gateway')?'A entrada Google ainda precisa ser publicada no Render. Seu acesso atual continua disponível.':'A entrada foi preparada. Falta o administrador cadastrar as credenciais OAuth no Render.'}</p>${status.callback?`<div class="field"><label>Endereço de retorno no Google Cloud</label><input readonly value="${esc(status.callback)}"></div>`:''}${status.configured?`<form><label style="display:flex;gap:10px;margin-top:18px"><input type="checkbox" name="confirm" required style="width:auto">Quero permitir que a conta Google escolhida acesse esta empresa e suas configurações.</label><p class="footnote">Escolha sua conta Google. Se uma tentativa antiga criou uma empresa vazia, o vínculo pode ser recuperado com segurança. O vínculo expira em dez minutos.</p><div class="formerror" role="alert"></div><div class="modalfoot"><button type="button" class="btn" data-close>Voltar</button><button class="btn primary">Escolher conta Google</button></div></form>`:'<p class="footnote">São necessárias GOOGLE_CLIENT_ID e GOOGLE_CLIENT_SECRET de um cliente OAuth do tipo Aplicativo da Web. A chave do Gemini não serve para entrar.</p><div class="modalfoot"><button class="btn" data-close>Entendi</button></div>'}`,async(f,form)=>{const submit=form.querySelector('.primary');submit.disabled=true;try{await flushCloud();const result=await api('/google-account/start',{method:'POST',body:{confirm:f.get('confirm')==='on'}});const target=new URL(result.url),expected=new URL(cloud.features.googleGateway);if(target.origin!==expected.origin||target.pathname!=='/auth/google/start')throw Error('Endereço de entrada inválido.');window.location.assign(target.href);}catch(e){error(form,e.message);submit.disabled=false;}});}catch(e){toast(e.message);}}

window.addEventListener('beforeunload',e=>{if(cloud.pending||cloud.error||cloud.menuDirty||cloud.menuBusy||cloud.sending||cloud.replySending||Object.values(cloud.replyDrafts||{}).some(Boolean)){e.preventDefault();e.returnValue='';}});
